// Logic tests for the pane helpers that do not need a display.
//
// This TU includes src/panes.cpp so the file-static helpers (quick filter
// matcher, the row->entry `view` map, marking, clipboard path helpers) can be
// exercised directly. Run through `ctest` or ./build/test-panes.

#include "../src/panes.cpp"
#include "version.h"   // generated into build/generated by CMake

#include <cstdio>
#include <string>
#include <sys/stat.h>
#include <unistd.h>

static int failures = 0;
static int checks = 0;

#define CHECK(cond)                                                        \
    do {                                                                   \
        checks++;                                                          \
        if (!(cond)) {                                                     \
            failures++;                                                    \
            printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);         \
        }                                                                  \
    } while (0)

static void touch_file(const std::string& dir, const char* name) {
    std::string p = dir + "/" + name;
    FILE* f = fopen(p.c_str(), "wb");
    if (f) { fputs("hello\n", f); fclose(f); }
}

static void sh(const std::string& cmd) { int rc = system(cmd.c_str()); (void)rc; }

static int idx_of(const Pane& p, const char* name) {
    for (int i = 0; i < p.entry_count; i++)
        if (strcmp(p.entries[i]->name, name) == 0) return i;
    return -1;
}

// F5 and F6 stop at the operation dialog instead of acting, so a test that wants
// the operation to happen has to accept the destination and then pump the
// deferred table, which is what the main loop does between frames.
static void accept_op(AppPanes* app) {
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    app_panes_run_pending(app);
}

// Walk the list with nav_step the way the arrow keys do.
static std::vector<int> walk(const Pane& p, int from, int dir) {
    std::vector<int> out;
    int cur = from;
    while (cur >= 0) {
        out.push_back(cur);
        cur = nav_step(p, cur, dir);
    }
    return out;
}

static void test_matcher() {
    CHECK(filter_matches("alpha.txt", ""));
    CHECK(filter_matches("alpha.txt", "ph"));
    CHECK(filter_matches("alpha.txt", "PH"));          // case-insensitive
    CHECK(filter_matches("alpha.txt", "a.txt"));        // not a substring -> no
    CHECK(!filter_matches("gamma.log", "ph"));
    CHECK(filter_matches("alpha.txt", "*.txt"));        // glob
    CHECK(!filter_matches("gamma.log", "*.txt"));
    CHECK(filter_matches("a.txt", "a?txt"));
    CHECK(filter_matches("alpha.txt", "*"));
    CHECK(!glob_match("*.txt", "alpha.tx"));
}

static void test_view_and_nav(Pane& p) {
    // No filter: view is the identity map over entries.
    CHECK((int)p.view.size() == p.entry_count);
    CHECK(p.view.front() == 0);

    snprintf(p.filter, sizeof(p.filter), ".txt");
    rebuild_view(p);
    CHECK(strcmp(p.filter_applied, ".txt") == 0);

    // Every visible row matches, except ".." which always stays visible.
    for (int i : p.view) {
        const char* n = p.entries[i]->name;
        CHECK(strcmp(n, "..") == 0 || filter_matches(n, ".txt"));
    }
    CHECK(idx_of(p, "alpha.txt") >= 0);
    CHECK(std::find(p.view.begin(), p.view.end(), idx_of(p, "beta.txt")) != p.view.end());
    CHECK(std::find(p.view.begin(), p.view.end(), idx_of(p, "gamma.log")) == p.view.end());
    CHECK(std::find(p.view.begin(), p.view.end(), idx_of(p, "..")) != p.view.end());

    // Arrow-key walking visits exactly the visible rows, in view order.
    std::vector<int> down = walk(p, first_visible(p), 1);
    CHECK(down == std::vector<int>(p.view.begin(), p.view.end()));
    std::vector<int> up = walk(p, last_visible(p), -1);
    std::reverse(up.begin(), up.end());
    CHECK(up == std::vector<int>(p.view.begin(), p.view.end()));

    // A cursor left on a hidden entry still steps to a visible neighbour.
    int hidden = idx_of(p, "gamma.log");
    CHECK(hidden >= 0);
    CHECK(row_visible(p, hidden) == false);
    CHECK(nav_step(p, hidden, 1) >= 0 || nav_step(p, hidden, -1) >= 0);

    // Page steps stay inside the visible rows.
    int pg = nav_page(p, first_visible(p), 1, 2);
    CHECK(pg < 0 || row_visible(p, pg));
    CHECK(nav_page(p, first_visible(p), -1, 5) == -1);
    CHECK(nav_page(p, last_visible(p), 1, 5) == -1);

    // Range marking while filtered only touches visible rows.
    for (size_t i = 0; i < p.marked.size(); i++) p.marked[i] = false;
    mark_range(p, first_visible(p), last_visible(p));
    for (int i = 0; i < p.entry_count; i++) {
        bool vis = row_visible(p, i);
        bool mk = i < (int)p.marked.size() && p.marked[i];
        if (!vis) CHECK(mk == false);
    }
    CHECK(marked_count(p) == (int)p.view.size() - 1);  // ".." is never marked

    // Clearing the filter restores the full list.
    p.filter[0] = '\0';
    rebuild_view(p);
    CHECK((int)p.view.size() == p.entry_count);
}

static void test_mark_history(Pane& p) {
    p.filter[0] = '\0';
    rebuild_view(p);
    p.mark_undo.clear();
    for (size_t i = 0; i < p.marked.size(); i++) p.marked[i] = false;

    select_all_marks(p);
    CHECK(marked_count(p) == p.entry_count - 1);   // everything but ".."
    restore_marks(p);
    CHECK(marked_count(p) == 0);

    // Two bulk ops stack, so Num/ walks back one step at a time.
    toggle_mark(p, idx_of(p, "alpha.txt"));
    select_all_marks(p);
    invert_marks(p);
    CHECK(marked_count(p) == 0);
    restore_marks(p);
    CHECK(marked_count(p) == p.entry_count - 1);
    restore_marks(p);
    CHECK(marked_count(p) == 1);
}

static void test_step_marks(Pane& p) {
    p.filter[0] = '\0';
    rebuild_view(p);
    for (size_t i = 0; i < p.marked.size(); i++) p.marked[i] = false;

    // Num+ marks the cursor row and steps to the next visible row.
    p.selected = first_visible(p);
    int expect = nav_step(p, p.selected, 1);
    step_marks(p, true);
    CHECK(marked_count(p) <= 1);
    CHECK(p.selected == expect);

    // With a filter, the step skips hidden rows.
    snprintf(p.filter, sizeof(p.filter), ".txt");
    rebuild_view(p);
    int from = idx_of(p, "alpha.txt");
    int nxt = nav_step(p, from, 1);
    CHECK(nxt >= 0 && row_visible(p, nxt));
    p.filter[0] = '\0';
    rebuild_view(p);
}

static void test_clipboard_paths(Pane& p) {
    CHECK(strcmp(path_basename("/a/b/c.txt"), "c.txt") == 0);
    CHECK(strcmp(path_basename("c.txt"), "c.txt") == 0);
    char parent[512];
    path_parent_dir("/a/b/c.txt", parent, sizeof(parent));
    CHECK(strcmp(parent, "/a/b") == 0);

    for (size_t i = 0; i < p.marked.size(); i++) p.marked[i] = false;
    p.selected = idx_of(p, "beta.txt");
    StringList one = target_paths(p);
    CHECK(one.size() == 1);
    CHECK(one.size() == 1 && strstr(one[0].c_str(), "/beta.txt") != nullptr);

    toggle_mark(p, idx_of(p, "alpha.txt"));
    toggle_mark(p, idx_of(p, "gamma.log"));
    StringList many = target_paths(p);
    CHECK(many.size() == 2);   // marks win over the cursor row

    int existing = count_existing_paths(p.current_dir, many);
    CHECK(existing == 2);      // both are real files in this directory
    CHECK(count_existing_paths("/nonexistent-dir-xyz", many) == 0);
}

static void test_refresh_clears_filter(Pane& p) {
    snprintf(p.filter, sizeof(p.filter), ".txt");
    rebuild_view(p);
    CHECK((int)p.view.size() < p.entry_count);

    // A refresh of the same directory keeps the filter (F5/F6/F8 reloads).
    refresh_pane(&p, p.current_dir);
    CHECK(strcmp(p.filter, ".txt") == 0);
    CHECK((int)p.view.size() < p.entry_count);

    // Changing directory drops it, like TC.
    char parent[4200];
    snprintf(parent, sizeof(parent), "%s", p.current_dir);
    char sub[4200];
    snprintf(sub, sizeof(sub), "%s/sub", parent);
    refresh_pane(&p, sub);
    CHECK(p.filter[0] == '\0');
    CHECK((int)p.view.size() == p.entry_count);
    refresh_pane(&p, parent);
}

static void test_tabs(Pane& p, const char* root) {
    refresh_pane(&p, root);
    p.tab_count = 1; p.tab_active = 0;
    snprintf(p.tabs[0].dir, sizeof(p.tabs[0].dir), "%s", root);

    tab_new(&p, true);
    CHECK(p.tab_count == 2);
    CHECK(p.tab_active == 1);

    // Ctrl+Shift+T: appended but not activated.
    tab_new(&p, false);
    CHECK(p.tab_count == 3);
    CHECK(p.tab_active == 1);

    tab_cycle(&p, 1);
    CHECK(p.tab_active == 2);

    // Ctrl+Shift+W: everything but the tab being shown, and it keeps its dir.
    tab_close_all(&p);
    CHECK(p.tab_count == 1);
    CHECK(p.tab_active == 0);
    CHECK(strcmp(p.tabs[0].dir, root) == 0);
    CHECK(strcmp(p.current_dir, root) == 0);

    // The floor is one tab: closing the last one is a no-op.
    tab_close(&p);
    tab_close_all(&p);
    CHECK(p.tab_count == 1);
}

// Ctrl+B branch view: the pane is replaced by the flattened subtree, and every
// row keeps a relative path so operations still address the right file.
static void test_branch_view(AppPanes* app, Pane& p) {
    CHECK(p.list_mode == LIST_NORMAL);
    CHECK(strcmp(entry_rel(p, idx_of(p, "alpha.txt")), "alpha.txt") == 0);

    branch_toggle(app, p, false);
    CHECK(p.list_mode == LIST_BRANCH);
    CHECK((int)p.rel.size() == p.entry_count);
    // a, a/deep, a/deep/x.txt, a/inner.txt, alpha.txt, beta.txt, gamma.log
    CHECK(p.entry_count == 7);
    CHECK(strcmp(entry_rel(p, idx_of(p, "x.txt")), "sub/deep/x.txt") == 0);
    CHECK(strcmp(entry_rel(p, idx_of(p, "sub")), "sub") == 0);
    CHECK((int)p.marked.size() == p.entry_count);
    CHECK((int)p.dir_size.size() == p.entry_count);
    CHECK(idx_of(p, "..") < 0);   // branch view has no parent row

    // The filter works on relative paths in branch view.
    snprintf(p.filter, sizeof(p.filter), "deep");
    rebuild_view(p);
    CHECK((int)p.view.size() == 2);   // sub/deep and sub/deep/x.txt
    p.filter[0] = '\0';
    rebuild_view(p);

    // Ctrl+B again leaves branch view.
    branch_toggle(app, p, false);
    CHECK(p.list_mode == LIST_NORMAL);
    CHECK(p.rel.empty());
    CHECK(p.entry_count == 5);

    // Ctrl+Shift+B walks only the marked directories.
    toggle_mark(p, idx_of(p, "sub"));
    branch_toggle(app, p, true);
    CHECK(p.list_mode == LIST_BRANCH);
    CHECK(p.entry_count == 3);
    CHECK(strcmp(entry_rel(p, idx_of(p, "x.txt")), "sub/deep/x.txt") == 0);
    branch_toggle(app, p, true);
}

// fs_list_tree: depth cap, row cap, dotfiles, and symlinks are not followed.
static void test_fs_list_tree() {
    char tm[] = "/tmp/mc-tree-XXXXXX";
    const char* d = mkdtemp(tm);
    if (!d) { CHECK(false); return; }
    std::string root(d);

    mkdir((root + "/a").c_str(), 0755);
    mkdir((root + "/a/b").c_str(), 0755);
    touch_file(root + "/a/b", "deep.txt");
    touch_file(root, ".dot");
    symlink(root.c_str(), (root + "/loop").c_str());   // a loop: must not be walked

    std::vector<FsTreeEntry> t;
    CHECK(fs_list_tree(root.c_str(), &t, 10, 1000) == 4);   // a, a/b, a/b/deep.txt, loop
    CHECK(strcmp(t[0].rel, "a") == 0);
    CHECK(strcmp(t[1].rel, "a/b") == 0);
    CHECK(strcmp(t[2].rel, "a/b/deep.txt") == 0);
    CHECK(S_ISDIR(t[0].mode));
    CHECK(!S_ISDIR(t[2].mode));

    CHECK(fs_list_tree(root.c_str(), &t, 1, 1000) == 2);    // a, loop
    CHECK(fs_list_tree(root.c_str(), &t, 10, 2) == 2);      // row cap
    CHECK(fs_list_tree(root.c_str(), &t, 0, 1000) == 0);

    fs_set_show_hidden(true);
    CHECK(fs_list_tree(root.c_str(), &t, 10, 1000) == 5);   // + .dot
    fs_set_show_hidden(false);
}

// Phase F primitives: fs_touch never clobbers, fs_symlink stores an absolute
// body, and the in-place copy picks a free ".copy" slot.
static void test_fs_helpers(const std::string& root) {
    CHECK(fs_touch((root + "/fresh.txt").c_str()));
    CHECK(fs_exists((root + "/fresh.txt").c_str()));
    CHECK(!fs_touch((root + "/fresh.txt").c_str()));   // O_EXCL: never truncates

    CHECK(fs_symlink((root + "/alpha.txt").c_str(), (root + "/link.txt").c_str()));
    CHECK(fs_exists((root + "/link.txt").c_str()));
    char buf[512];
    ssize_t n = readlink((root + "/link.txt").c_str(), buf, sizeof(buf) - 1);
    CHECK(n > 0);
    if (n > 0) {
        buf[n] = '\0';
        CHECK(strcmp(buf, (root + "/alpha.txt").c_str()) == 0);
    }
}

static void test_unique_copy_name(const std::string& root) {
    char out[4100];
    unique_copy_name(root.c_str(), "alpha.txt", out, sizeof(out));
    CHECK(strcmp(out, (root + "/alpha.txt.copy").c_str()) == 0);
    CHECK(fs_touch((root + "/alpha.txt.copy").c_str()));
    unique_copy_name(root.c_str(), "alpha.txt", out, sizeof(out));
    CHECK(strcmp(out, (root + "/alpha.txt.copy.1").c_str()) == 0);
    CHECK(fs_touch((root + "/alpha.txt.copy.1").c_str()));
    unique_copy_name(root.c_str(), "alpha.txt", out, sizeof(out));
    CHECK(strcmp(out, (root + "/alpha.txt.copy.2").c_str()) == 0);
}

// The trash half of TC's delete split. Availability is probed once and cached;
// a path no helper can resolve must fail rather than fall through silently.
static void test_trash_helpers(void) {
    bool a = fs_trash_available();
    CHECK(a == fs_trash_available());
    CHECK(!fs_trash("/mc-clone-does-not-exist-xyzzy"));
}

// TC quick search: prefix match from the cursor forward, wrapping, extending
// the word, and respecting the filtered view. A miss leaves the cursor alone.
static void test_quick_search(AppPanes* app, Pane& p) {
    p.quick_active = false; p.quick[0] = '\0';
    p.selected = idx_of(p, "alpha.txt");
    quick_search(app, p, 'b');
    CHECK(p.quick_active);
    CHECK(strcmp(p.quick, "b") == 0);
    CHECK(strcmp(entry_rel(p, p.selected), "beta.txt") == 0);

    quick_search(app, p, 'x');                 // "bx": no match, cursor stays
    CHECK(strcmp(p.quick, "bx") == 0);
    CHECK(strcmp(entry_rel(p, p.selected), "beta.txt") == 0);

    p.quick_active = false; p.quick[0] = '\0';
    p.selected = idx_of(p, "beta.txt");
    quick_search(app, p, 'a');                 // wraps past the end back to alpha
    CHECK(strcmp(entry_rel(p, p.selected), "alpha.txt") == 0);

    p.quick_active = false; p.quick[0] = '\0';
    p.selected = idx_of(p, "alpha.txt");
    snprintf(p.filter, sizeof(p.filter), "sub");
    rebuild_view(p);
    quick_search(app, p, 's');                 // only visible rows are searched
    CHECK(strcmp(entry_rel(p, p.selected), "sub") == 0);
    quick_search(app, p, 'u');                 // "su" extends the word
    CHECK(strcmp(entry_rel(p, p.selected), "sub") == 0);
    p.filter[0] = '\0';
    rebuild_view(p);
    p.quick_active = false; p.quick[0] = '\0';
}

// Shift+F1 column set: parsing tolerates case and padding, unknown keys are
// dropped, and the render cache must notice a rewritten spec.
static void test_columns(AppPanes* app) {
    bool on[COL_N];
    columns_parse("name,size,date,perms", on);
    CHECK(on[COL_NAME] && on[COL_SIZE] && on[COL_DATE] && on[COL_PERMS]);
    CHECK(!on[COL_EXT] && !on[COL_TYPE]);

    columns_parse("name, ext , TYPE", on);
    CHECK(on[COL_EXT] && on[COL_TYPE] && !on[COL_SIZE]);

    columns_parse("name,name,bogus", on);
    CHECK(on[COL_NAME]);
    CHECK(!on[COL_EXT] && !on[COL_SIZE] && !on[COL_DATE] && !on[COL_PERMS] && !on[COL_TYPE]);

    for (int c = 0; c < COL_N; c++) on[c] = (c == COL_NAME || c == COL_EXT || c == COL_TYPE);
    columns_write(app, on);
    CHECK(strcmp(app->columns, "name,ext,type") == 0);
    columns_spec(app, on);
    CHECK(on[COL_EXT] && on[COL_TYPE] && !on[COL_SIZE]);

    CHECK(strcmp(col_ext("archive.tar.gz"), "gz") == 0);
    CHECK(strcmp(col_ext("Makefile"), "") == 0);
    CHECK(strcmp(col_ext(".hidden"), "") == 0);      // no extension on dotfiles
    CHECK(strcmp(col_ext("README."), "") == 0);

    FileEntry fe;
    memset(&fe, 0, sizeof(fe));
    fe.mode = S_IFDIR | 0755;
    CHECK(strcmp(col_type(&fe, true, false), "DIR") == 0);
    fe.mode = S_IFLNK | 0777;
    CHECK(strcmp(col_type(&fe, false, false), "LNK") == 0);
    fe.mode = S_IFREG | 0755;
    CHECK(strcmp(col_type(&fe, false, true), "EXE") == 0);
    fe.mode = S_IFREG | 0644;
    CHECK(strcmp(col_type(&fe, false, false), "FILE") == 0);

    snprintf(app->columns, sizeof(app->columns), "name,size,date,perms");
}

// TC tree panel: the model is per pane, expand/collapse is symmetric, and the
// arrow keys drive it without touching the file rows.
static void test_tree_panel(AppPanes* app, Pane& p, const std::string& root) {
    snprintf(p.current_dir, sizeof(p.current_dir), "%s", root.c_str());
    tree_fill(p);
    CHECK(strcmp(p.tree_rows[0].path, root.c_str()) == 0);
    CHECK(p.tree_rows[0].depth == 0 && p.tree_rows[0].expanded);
    CHECK(p.tree_rows.size() >= 2);            // root + sub

    int sub = -1;
    const std::string subpath = root + "/sub";
    for (int i = 1; i < (int)p.tree_rows.size(); i++)
        if (p.tree_rows[i].path == subpath) sub = i;
    CHECK(sub >= 0);

    size_t before = p.tree_rows.size();
    tree_toggle(p, sub);                        // sub/deep splices in
    CHECK(p.tree_rows.size() == before + 1);
    CHECK(p.tree_rows[sub + 1].depth == p.tree_rows[sub].depth + 1);
    tree_toggle(p, sub);                        // and comes back out symmetrically
    CHECK(p.tree_rows.size() == before);

    // Each pane owns its model: expanding in one must not move the other.
    snprintf(app->right.current_dir, sizeof(app->right.current_dir), "%s", root.c_str());
    app->right.tree_rows.clear();
    tree_fill(app->right);
    CHECK(app->right.tree_rows.size() == p.tree_rows.size());
    tree_toggle(app->right, sub);
    CHECK(app->right.tree_rows.size() == p.tree_rows.size() + 1);
    app->right.tree_rows.clear();

    p.tree_selected = 0;
    CHECK(tree_nav(app, p, SDLK_DOWN));
    CHECK(p.tree_selected == 1);
    CHECK(tree_nav(app, p, SDLK_UP));
    CHECK(p.tree_selected == 0);
    CHECK(tree_nav(app, p, SDLK_UP));           // clamped at the top
    CHECK(p.tree_selected == 0);
    CHECK(tree_nav(app, p, SDLK_END));
    int end = p.tree_selected;
    CHECK(end == (int)p.tree_rows.size() - 1);
    CHECK(tree_nav(app, p, SDLK_LEFT));         // collapse, or jump to the parent
    CHECK(p.tree_selected <= end);
    CHECK(!tree_nav(app, p, SDLK_F3));          // unrelated keys fall through

    tree_mode_toggle(app, p, TREE_EMBED);
    CHECK(p.tree_mode == TREE_EMBED);
    tree_mode_toggle(app, p, TREE_EMBED);       // same mode again turns it off
    CHECK(p.tree_mode == TREE_OFF);
    tree_mode_toggle(app, p, TREE_SPLIT);
    CHECK(p.tree_mode == TREE_SPLIT);
    tree_mode_toggle(app, p, TREE_EMBED);       // switching kinds, not off
    CHECK(p.tree_mode == TREE_EMBED);
    p.tree_mode = TREE_OFF;
}

// TC's archive keys must stay reserved. Alt+F5 leaking into plain F5 is what
// made the app copy files when the user asked it to pack them.
static void test_archive_keys(void) {
    CHECK(is_archive_key(SDLK_F5, SDL_KMOD_ALT));
    CHECK(is_archive_key(SDLK_F5, SDL_KMOD_ALT | SDL_KMOD_SHIFT));
    CHECK(is_archive_key(SDLK_F6, SDL_KMOD_ALT));
    CHECK(is_archive_key(SDLK_F9, SDL_KMOD_ALT));
    CHECK(is_archive_key(SDLK_F9, SDL_KMOD_ALT | SDL_KMOD_SHIFT));
    // plain and Ctrl forms belong to copy / move / the pane menu
    CHECK(!is_archive_key(SDLK_F5, SDL_KMOD_NONE));
    CHECK(!is_archive_key(SDLK_F5, SDL_KMOD_SHIFT));
    CHECK(!is_archive_key(SDLK_F6, SDL_KMOD_NONE));
    CHECK(!is_archive_key(SDLK_F9, SDL_KMOD_NONE));
    CHECK(!is_archive_key(SDLK_F5, SDL_KMOD_CTRL));
    // neighbouring Alt keys are real features, not archive keys
    CHECK(!is_archive_key(SDLK_F4, SDL_KMOD_ALT));
    CHECK(!is_archive_key(SDLK_F7, SDL_KMOD_ALT));
    CHECK(!is_archive_key(SDLK_F8, SDL_KMOD_ALT));
    CHECK(!is_archive_key(SDLK_F10, SDL_KMOD_ALT));
}

// Drive the real key handler, not just the classifier: this is the path that
// regressed, where Alt+F5 reached the plain F5 handler and copied files.
static void test_archive_keys_live(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    app->left_focus = true;
    refresh_pane(&p, root.c_str());
    int before = p.entry_count;
    bool copy_existed = fs_exists((root + "/alpha.txt.copy").c_str());

    int ai = idx_of(p, "alpha.txt");
    CHECK(ai >= 0);
    p.selected = ai;
    p.marked[ai] = true;

    // Alt+F5 opens the pack dialog; it must not fall through to a copy.
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT);
    CHECK(app->pack_open);
    CHECK(!app->prog_active);
    CHECK(app->clipboard.paths.empty());      // nothing queued for a copy
    app->pack_open = false;
    app->pack_names.clear();

    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT | SDL_KMOD_SHIFT);
    CHECK(app->pack_open);
    CHECK(app->pack_delete);                  // the sources are offered for removal
    CHECK(fs_exists((root + "/alpha.txt").c_str()));   // not deleted
    app->pack_open = false;
    app->pack_names.clear();

    // With no archive under the cursor the extract keys say so and do nothing.
    app_panes_handle_key(app, SDLK_F6, SDL_KMOD_ALT);
    CHECK(strstr(app->status_msg, "No archive under the cursor") != NULL);
    CHECK(!app->prog_active);

    app_panes_handle_key(app, SDLK_F9, SDL_KMOD_ALT);
    CHECK(strstr(app->status_msg, "No archive under the cursor") != NULL);

    app->pane_menu_open = false;
    app_panes_handle_key(app, SDLK_F9, SDL_KMOD_ALT | SDL_KMOD_SHIFT);
    CHECK(!app->pane_menu_open);              // the pane menu stays shut
    CHECK(strstr(app->status_msg, "No archive under the cursor") != NULL);

    refresh_pane(&p, root.c_str());
    CHECK(p.entry_count == before);           // no copies, no .copy files, no moves
    CHECK(fs_exists((root + "/alpha.txt").c_str()));
    CHECK(fs_exists((root + "/alpha.txt.copy").c_str()) == copy_existed);
    clear_marks(p);

    // the unmodified key still opens the pane menu
    app_panes_handle_key(app, SDLK_F9, SDL_KMOD_NONE);
    CHECK(app->pane_menu_open);
    app->pane_menu_open = false;
}

static bool dir_exists(const std::string& p) {
    struct stat st;
    return stat(p.c_str(), &st) == 0 && S_ISDIR(st.st_mode);
}

// Enter on an archive opens it as a pane, exactly like a directory: rows, a
// virtual path the rest of the pane can carry, and folders inside it to walk.
static void test_archive_browse(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    app->left_focus = true;

    refresh_pane(&p, root.c_str());
    int zi = idx_of(p, "pkg.zip");
    CHECK(zi >= 0);
    CHECK(p.archive_path[0] == '\0');           // still a plain directory listing

    p.selected = zi;
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(strcmp(p.current_dir, (root + "/pkg.zip").c_str()) == 0);
    CHECK(p.list_mode == LIST_ARCHIVE);
    CHECK(strcmp(p.archive_path, (root + "/pkg.zip").c_str()) == 0);
    CHECK(p.archive_prefix[0] == '\0');
    CHECK(idx_of(p, "one.txt") >= 0);
    CHECK(idx_of(p, "two.txt") >= 0);
    CHECK(idx_of(p, "sub") >= 0);
    // The archive root carries a ".." row like any other directory. Without it
    // the only way out of an archive is a key nobody thinks to press.
    CHECK(idx_of(p, "..") == 0);
    p.selected = idx_of(p, "..");
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(p.list_mode == LIST_NORMAL);
    CHECK(strcmp(p.current_dir, root.c_str()) == 0);
    p.selected = idx_of(p, "pkg.zip");
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(p.list_mode == LIST_ARCHIVE);

    // A folder inside the archive is an ordinary row that can be walked into.
    p.selected = idx_of(p, "sub");
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(strcmp(p.archive_prefix, "sub") == 0);
    CHECK(idx_of(p, "..") >= 0);
    int ii = idx_of(p, "inner.txt");
    CHECK(ii >= 0);
    // A row's rel is relative to the level being listed, which is what makes the
    // virtual path come out right; the tool-facing member name is derived from
    // it plus the pane's prefix.
    CHECK(strcmp(p.rel[ii].c_str(), "inner.txt") == 0);
    CHECK(strcmp(member_raw(p, p.rel[ii].c_str()).c_str(), "sub/inner.txt") == 0);

    // Enter on a member unpacks just that one and opens the viewer; closing the
    // viewer takes the temporary directory with it.
    p.selected = ii;
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->viewer_open);
    CHECK(app->viewer_tmp_dir[0] != '\0');
    CHECK(dir_exists(app->viewer_tmp_dir));
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(!app->viewer_open);
    CHECK(app->viewer_tmp_dir[0] == '\0');
    CHECK(!dir_exists(app->viewer_tmp_dir));

    // Shift+F3 (view only the entry under the cursor) unpacks the same way.
    p.selected = ii;
    app_panes_handle_key(app, SDLK_F3, SDL_KMOD_SHIFT);
    CHECK(app->viewer_open);
    CHECK(app->viewer_tmp_dir[0] != '\0');
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(!dir_exists(app->viewer_tmp_dir));

    // Backspace leaves one level, and again leaves the archive.
    app_panes_handle_key(app, SDLK_BACKSPACE, SDL_KMOD_NONE);
    CHECK(p.archive_prefix[0] == '\0');
    app_panes_handle_key(app, SDLK_BACKSPACE, SDL_KMOD_NONE);
    CHECK(p.list_mode == LIST_NORMAL);
    CHECK(p.archive_path[0] == '\0');
    CHECK(strcmp(p.current_dir, root.c_str()) == 0);

    // The archive is still an ordinary file on disk afterwards.
    CHECK(fs_exists((root + "/pkg.zip").c_str()));
}

// Everything that would have to write through a virtual path says no instead of
// doing something half right.
static void test_archive_guards(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    app->left_focus = true;
    refresh_pane(&p, (root + "/pkg.zip").c_str());
    CHECK(p.archive_path[0] != '\0');
    int before = p.entry_count;
    p.selected = idx_of(p, "one.txt");

    app_panes_handle_key(app, SDLK_F8, SDL_KMOD_NONE);              // delete
    CHECK(strstr(app->status_msg, "archive") != NULL);
    app->confirm = CONF_NONE;

    app_panes_handle_key(app, SDLK_F2, SDL_KMOD_NONE);              // rename
    CHECK(app->op == OP_NONE);
    app_panes_handle_key(app, SDLK_F7, SDL_KMOD_NONE);              // mkdir
    CHECK(app->op == OP_NONE);
    app_panes_handle_key(app, SDLK_F4, SDL_KMOD_SHIFT);             // new file
    CHECK(app->op == OP_NONE);

    // F5 inside an archive copies members out into the other pane, so the guard
    // that matters is the destination: a second archive cannot be written into.
    refresh_pane(&app->right, (root + "/pkg.zip").c_str());
    CHECK(app->right.archive_path[0] != '\0');
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    CHECK(strstr(app->status_msg, "target pane is inside an archive") != NULL);
    CHECK(!app->prog_active);
    // A move would have to delete the member afterwards, which no format we can
    // write lets us do.
    app_panes_handle_key(app, SDLK_F6, SDL_KMOD_NONE);
    CHECK(strstr(app->status_msg, "cannot be written into") != NULL);
    CHECK(!app->prog_active);
    // Real files cannot be pasted in either.
    app->clipboard.paths.clear();
    app->clipboard.paths.push_back(root + "/pkg.zip");
    app->clipboard.cut = false;
    app->clipboard.archive[0] = '\0';
    app_panes_handle_key(app, SDLK_V, SDL_KMOD_CTRL);
    CHECK(strstr(app->status_msg, "read-only") != NULL);
    CHECK(p.entry_count == before);

    app->clipboard.paths.clear();
    app_panes_handle_key(app, SDLK_X, SDL_KMOD_CTRL);               // cut a member
    CHECK(app->clipboard.paths.empty());

    app_panes_handle_key(app, SDLK_B, SDL_KMOD_CTRL);               // branch view
    CHECK(p.list_mode == LIST_ARCHIVE);
    app_panes_handle_key(app, SDLK_F8, SDL_KMOD_CTRL | SDL_KMOD_SHIFT);   // tree panel
    CHECK(p.tree_mode == TREE_OFF);
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_ALT);           // properties
    CHECK(!app->props_open);
    app_panes_handle_key(app, SDLK_F3, SDL_KMOD_ALT);               // open with default app
    CHECK(strstr(app->status_msg, "extracted first") != NULL);
    app_panes_handle_key(app, SDLK_F4, SDL_KMOD_NONE);              // edit
    CHECK(strstr(app->status_msg, "real file") != NULL);

    // Ctrl+P puts the archive file on the command line, never the virtual path.
    app->cmd[0] = '\0';
    app_panes_handle_key(app, SDLK_P, SDL_KMOD_CTRL);
    CHECK(strstr(app->cmd, "pkg.zip") != NULL);
    CHECK(strstr(app->cmd, "pkg.zip/") == NULL);
    app->cmd[0] = '\0';

    refresh_pane(&p, (root + "/pkg.zip").c_str());
    CHECK(p.entry_count == before);
    CHECK(fs_exists((root + "/pkg.zip").c_str()));
}

// F5 inside an archive copies the marked members, or the cursor row, into the
// other pane's directory. It is an extraction: the archive stays byte for byte
// what it was, and only what was asked for comes out.
static void test_archive_f5_copy_out(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    app->left_focus = true;
    std::string out = root + "/out_f5";
    sh("rm -rf '" + out + "'");
    sh("mkdir -p '" + out + "'");
    refresh_pane(&app->right, out.c_str());
    refresh_pane(&p, (root + "/pkg.zip").c_str());
    CHECK(p.archive_path[0] != '\0');

    // Nothing marked: the row under the cursor alone, and the ".." row is never
    // a target even when the cursor sits on it.
    p.selected = idx_of(p, "one.txt");
    CHECK(p.selected >= 0);
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    CHECK(app->op == OP_COPY);          // F5 asks first, it does not act
    accept_op(app);
    CHECK(app->op == OP_NONE);
    CHECK(fs_exists((out + "/one.txt").c_str()));
    CHECK(!fs_exists((out + "/two.txt").c_str()));
    CHECK(strstr(app->status_msg, "Copied 1 member") != NULL);

    // Marked rows, one of them a folder: the folder comes out with its contents,
    // not as an empty directory, and keeps its path inside the archive.
    p.marked[idx_of(p, "two.txt")] = true;
    p.marked[idx_of(p, "sub")] = true;
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    accept_op(app);
    CHECK(fs_exists((out + "/two.txt").c_str()));
    CHECK(fs_exists((out + "/sub/inner.txt").c_str()));
    CHECK(!fs_exists((out + "/inner.txt").c_str()));
    CHECK(strstr(app->status_msg, "Copied 2 members") != NULL);
    for (int i = 0; i < p.entry_count; i++) p.marked[i] = false;

    // A level deeper, the member still lands at its archive path rather than in
    // the destination's top level, and the status line says so.
    std::string deep = root + "/out_f5_deep";
    sh("rm -rf '" + deep + "'");
    sh("mkdir -p '" + deep + "'");
    refresh_pane(&app->right, deep.c_str());
    app->cmd[0] = '\0';   // a leftover command line would make Enter run it
    p.selected = idx_of(p, "sub");
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(strcmp(p.archive_prefix, "sub") == 0);
    p.selected = idx_of(p, "inner.txt");
    CHECK(p.selected >= 0);
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    // Out of an archive the field is the folder the members land in, never a new
    // name: a member keeps the path it has inside the archive.
    CHECK(strcmp(app->op_name, deep.c_str()) == 0);
    accept_op(app);
    CHECK(fs_exists((deep + "/sub/inner.txt").c_str()));
    CHECK(!fs_exists((deep + "/inner.txt").c_str()));
    CHECK(strstr(app->status_msg, "preserved") != NULL);

    // The destination already holds that member, so F5 asks first and writes
    // nothing until the answer is Yes.
    refresh_pane(&app->right, out.c_str());
    sh("mkdir -p '" + out + "/sub' && printf 'OLD\n' > '" + out + "/sub/inner.txt'");
    long sentinel = 4;   // "OLD\n", against the member's own 6 bytes
    struct stat st0;
    CHECK(stat((out + "/sub/inner.txt").c_str(), &st0) == 0 && st0.st_size == sentinel);
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    accept_op(app);                     // Enter accepts the destination...
    CHECK(app->confirm == CONF_OVERWRITE_EXTRACT);   // ...and the existing file asks first
    struct stat st1;
    CHECK(stat((out + "/sub/inner.txt").c_str(), &st1) == 0 && st1.st_size == sentinel);
    confirm_yes(app);
    CHECK(app->confirm == CONF_NONE);
    struct stat st2;
    CHECK(stat((out + "/sub/inner.txt").c_str(), &st2) == 0 && st2.st_size != sentinel);

    // The Commands menu route reaches the same operation through the deferred
    // table, so it copies out as well.
    std::string out2 = root + "/out_f5_menu";
    sh("rm -rf '" + out2 + "'");
    sh("mkdir -p '" + out2 + "'");
    refresh_pane(&app->right, out2.c_str());
    refresh_pane(&p, (root + "/pkg.zip").c_str());
    p.selected = idx_of(p, "two.txt");
    CHECK(p.selected >= 0);
    app->pending_op = DEFER_COPY;
    app_panes_run_pending(app);
    CHECK(app->op == OP_COPY);          // the menu route opens the same dialog
    accept_op(app);
    CHECK(fs_exists((out2 + "/two.txt").c_str()));

    // And the archive itself is untouched by all of it.
    std::vector<ArchEntry> v;
    std::string err;
    CHECK(arch_list((root + "/pkg.zip").c_str(), &v, &err));
    CHECK(v.size() == 4);   // one.txt, two.txt, sub, sub/inner.txt
    sh("rm -rf '" + out + "' '" + out2 + "' '" + deep + "'");
}

// Ctrl+C inside an archive puts members on the clipboard; Ctrl+V in a real
// directory extracts exactly those.
static void test_archive_copy_out(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    app->left_focus = true;
    refresh_pane(&p, (root + "/pkg.zip").c_str());
    p.selected = idx_of(p, "one.txt");

    app_panes_handle_key(app, SDLK_C, SDL_KMOD_CTRL);
    CHECK(app->clipboard.paths.size() == 1);
    CHECK(strcmp(app->clipboard.archive, (root + "/pkg.zip").c_str()) == 0);

    sh("rm -rf '" + root + "/out'");
    sh("mkdir -p '" + root + "/out'");
    refresh_pane(&app->right, (root + "/out").c_str());
    app->left_focus = false;
    app_panes_handle_key(app, SDLK_V, SDL_KMOD_CTRL);
    CHECK(fs_exists((root + "/out/one.txt").c_str()));
    CHECK(!fs_exists((root + "/out/two.txt").c_str()));   // only what was copied
    CHECK(app->clipboard.paths.empty());
    CHECK(app->clipboard.archive[0] == '\0');

    // A normal copy afterwards clears the archive context, so a paste cannot go
    // back to extracting from the archive.
    app->left_focus = true;
    refresh_pane(&p, root.c_str());
    p.selected = idx_of(p, "alpha.txt");
    app_panes_handle_key(app, SDLK_C, SDL_KMOD_CTRL);
    CHECK(app->clipboard.archive[0] == '\0');
    CHECK(app->clipboard.paths.size() == 1);
    CHECK(app->clipboard.paths[0] == root + "/alpha.txt");
    app->clipboard.paths.clear();
}

// The archive operations themselves: pack, pack-and-delete, extract to the
// other pane, extract here, and the integrity test.
static void test_archive_ops(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    Pane& q = app->right;
    app->left_focus = true;

    sh("rm -rf '" + root + "/pack'");
    sh("mkdir -p '" + root + "/pack'");
    touch_file(root + "/pack", "a.txt");
    touch_file(root + "/pack", "b.txt");
    refresh_pane(&p, (root + "/pack").c_str());
    for (int i = 0; i < p.entry_count; i++)
        if (strcmp(p.entries[i]->name, "..") != 0) p.marked[i] = true;

    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT);
    CHECK(app->pack_open);
    CHECK(strcmp(app->pack_name, "archive") == 0);   // several sources: generic name
    snprintf(app->pack_name, sizeof(app->pack_name), "packed");
    pack_commit(app);
    CHECK(!app->pack_open);
    CHECK(fs_exists((root + "/pack/packed.zip").c_str()));
    std::vector<ArchEntry> members;
    std::string err;
    CHECK(arch_list((root + "/pack/packed.zip").c_str(), &members, &err));
    CHECK(arch_find(members, "a.txt") != NULL);
    CHECK(arch_find(members, "b.txt") != NULL);
    CHECK(fs_exists((root + "/pack/a.txt").c_str()));  // a plain pack keeps the sources

    // Alt+Shift+F5 is a move into the archive: the sources go afterwards.
    refresh_pane(&p, (root + "/pack").c_str());
    for (int i = 0; i < p.entry_count; i++)
        if (strcmp(p.entries[i]->name, "..") != 0 && strcmp(p.entries[i]->name, "packed.zip") != 0)
            p.marked[i] = true;
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT | SDL_KMOD_SHIFT);
    CHECK(app->pack_open);
    CHECK(app->pack_delete);
    snprintf(app->pack_name, sizeof(app->pack_name), "moved");
    pack_commit(app);
    CHECK(fs_exists((root + "/pack/moved.zip").c_str()));
    CHECK(!fs_exists((root + "/pack/a.txt").c_str()));
    CHECK(!fs_exists((root + "/pack/b.txt").c_str()));

    // Alt+F6 extracts the archive under the cursor into the other pane.
    sh("rm -rf '" + root + "/out2'");
    sh("mkdir -p '" + root + "/out2'");
    refresh_pane(&p, root.c_str());
    refresh_pane(&q, (root + "/out2").c_str());
    app->left_focus = true;
    p.selected = idx_of(p, "pkg.zip");
    app_panes_handle_key(app, SDLK_F6, SDL_KMOD_ALT);
    CHECK(strstr(app->status_msg, "Extracted") != NULL);
    CHECK(fs_exists((root + "/out2/one.txt").c_str()));
    CHECK(fs_exists((root + "/out2/sub/inner.txt").c_str()));

    // Alt+F9 extracts into this pane's directory.
    sh("rm -rf '" + root + "/here'");
    sh("mkdir -p '" + root + "/here'");
    sh("cp '" + root + "/pkg.zip' '" + root + "/here/'");
    refresh_pane(&p, (root + "/here").c_str());
    p.selected = idx_of(p, "pkg.zip");
    app_panes_handle_key(app, SDLK_F9, SDL_KMOD_ALT);
    CHECK(strstr(app->status_msg, "Extracted") != NULL);
    CHECK(fs_exists((root + "/here/one.txt").c_str()));

    // Alt+Shift+F9 reads every member without writing anything. The extract
    // refreshed the pane, so the cursor has to be placed again.
    p.selected = idx_of(p, "pkg.zip");
    app_panes_handle_key(app, SDLK_F9, SDL_KMOD_ALT | SDL_KMOD_SHIFT);
    CHECK(strstr(app->status_msg, "Archive OK") != NULL);

    // Extracting while the other pane is also inside an archive is refused
    // rather than writing a virtual path.
    refresh_pane(&q, (root + "/pkg.zip").c_str());
    refresh_pane(&p, root.c_str());
    app->left_focus = true;
    p.selected = idx_of(p, "pkg.zip");
    app_panes_handle_key(app, SDLK_F6, SDL_KMOD_ALT);
    CHECK(strstr(app->status_msg, "inside an archive") != NULL);
    refresh_pane(&q, root.c_str());

    sh("rm -rf '" + root + "/pack' '" + root + "/out2' '" + root + "/here'");
}

static int kind_idx(ArchKind k) {
    const std::vector<ArchKind>& ks = arch_pack_kinds();
    for (int i = 0; i < (int)ks.size(); i++) if (ks[i] == k) return i;
    return -1;
}

// The dialog's choices have to reach the tool, and a choice the format cannot
// honour has to be refused in the dialog rather than quietly dropped on the way
// to it - a "password protected" archive that is not encrypted is worse than an
// error message.
static void test_pack_options(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    app->left_focus = true;

    sh("rm -rf '" + root + "/opts' '" + root + "/yes' '" + root + "/nope'");
    sh("mkdir -p '" + root + "/opts'");
    // Redundant content, so a compression level has something to bite on.
    for (int i = 0; i < 3; i++) {
        std::string path = root + "/opts/f" + std::to_string(i) + ".txt";
        FILE* f = fopen(path.c_str(), "wb");
        if (f) { for (int k = 0; k < 20000; k++) fwrite("abcdefgh", 1, 8, f); fclose(f); }
    }
    auto mark_all = [&]() {
        refresh_pane(&p, (root + "/opts").c_str());
        for (int i = 0; i < p.entry_count; i++)
            if (strcmp(p.entries[i]->name, "..") != 0) p.marked[i] = true;
    };

    CHECK(kind_idx(ARCH_7Z) >= 0);
    CHECK(kind_idx(ARCH_ZIP) >= 0);
    CHECK(kind_idx(ARCH_TAR_GZ) >= 0);

    // A 7z with a password and a chosen level.
    mark_all();
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT);
    app->pack_kind_idx = kind_idx(ARCH_7Z);
    snprintf(app->pack_name, sizeof(app->pack_name), "secret");
    app->pack_use_level = true;
    app->pack_level = 9;
    snprintf(app->pack_password, sizeof(app->pack_password), "hunter2");
    pack_commit(app);
    CHECK(!app->pack_open);
    std::string sev = root + "/opts/secret.7z";
    CHECK(fs_exists(sev.c_str()));

    // It really is encrypted: the tool cannot read it back without the password.
    sh("mkdir -p '" + root + "/nope'");
    std::string err;
    CHECK(!arch_extract(sev.c_str(), (root + "/nope").c_str(), nullptr, nullptr, &err));
    CHECK(!fs_exists((root + "/nope/f0.txt").c_str()));
    sh("mkdir -p '" + root + "/yes'");
    int rc = system(("7z x '" + sev + "' -o'" + root + "/yes' -p'hunter2' -y > /dev/null 2>&1").c_str());
    CHECK(rc == 0);
    CHECK(fs_exists((root + "/yes/f0.txt").c_str()));

    // tar cannot encrypt. The dialog stays open so the choice can be fixed, and
    // nothing half-made is left behind.
    mark_all();
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT);
    app->pack_kind_idx = kind_idx(ARCH_TAR_GZ);
    snprintf(app->pack_name, sizeof(app->pack_name), "plain");
    snprintf(app->pack_password, sizeof(app->pack_password), "hunter2");
    pack_commit(app);
    CHECK(app->pack_open);
    CHECK(strstr(app->status_msg, "encrypt") != NULL);
    CHECK(!fs_exists((root + "/opts/plain.tar.gz").c_str()));
    app->pack_password[0] = '\0';
    pack_commit(app);                       // same name, now without a password
    CHECK(!app->pack_open);
    CHECK(fs_exists((root + "/opts/plain.tar.gz").c_str()));

    // Volumes: refused for zip, because a split .zip comes back unreadable; and
    // for 7z the set has to read back as one archive.
    mark_all();
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT);
    app->pack_kind_idx = kind_idx(ARCH_ZIP);
    snprintf(app->pack_name, sizeof(app->pack_name), "split");
    app->pack_volume_bytes = 1024 * 1024;
    pack_commit(app);
    CHECK(app->pack_open);
    CHECK(strstr(app->status_msg, "volumes") != NULL);
    CHECK(!fs_exists((root + "/opts/split.zip").c_str()));

    app->pack_kind_idx = kind_idx(ARCH_7Z);
    app->pack_password[0] = '\0';
    pack_commit(app);
    CHECK(!app->pack_open);
    CHECK(fs_exists((root + "/opts/split.7z.001").c_str()));
    sh("mkdir -p '" + root + "/volout'");
    CHECK(arch_extract((root + "/opts/split.7z.001").c_str(), (root + "/volout").c_str(),
                       nullptr, nullptr, &err));
    CHECK(fs_exists((root + "/volout/f0.txt").c_str()));

    // The format owns the suffix, so a name typed with the wrong one still
    // produces the archive the dialog said it would.
    mark_all();
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_ALT);
    app->pack_kind_idx = kind_idx(ARCH_TAR_XZ);
    snprintf(app->pack_name, sizeof(app->pack_name), "mismatched.zip");
    app->pack_volume_bytes = 0;
    pack_commit(app);
    CHECK(!app->pack_open);
    CHECK(fs_exists((root + "/opts/mismatched.tar.xz").c_str()));
    CHECK(!fs_exists((root + "/opts/mismatched.zip").c_str()));

    sh("rm -rf '" + root + "/opts' '" + root + "/yes' '" + root + "/nope' '" + root + "/volout'");
}

// TC Ctrl+P (path into the command line) and Ctrl+I (switch to the target
// pane). Ctrl+I used to invert the marks, which is TC's Num*.
static void test_ctrl_p_and_i(AppPanes* app, const std::string& root) {
    // The key handler reaches the panes through AppPanes, so drive app->left
    // rather than the standalone test pane.
    Pane& p = app->left;
    app->left_focus = true;
    refresh_pane(&p, root.c_str());
    app->cmd[0] = '\0';

    app_panes_handle_key(app, SDLK_P, SDL_KMOD_CTRL);
    CHECK(strcmp(app->cmd, p.current_dir) == 0);

    // Existing text is kept, the path is appended.
    snprintf(app->cmd, sizeof(app->cmd), "rm ");
    app_panes_handle_key(app, SDLK_P, SDL_KMOD_CTRL);
    CHECK(strncmp(app->cmd, "rm ", 3) == 0);
    CHECK(strcmp(app->cmd + 3, p.current_dir) == 0);

    // No trailing space: one is inserted, so the path cannot glue onto a word.
    snprintf(app->cmd, sizeof(app->cmd), "rm");
    app_panes_handle_key(app, SDLK_P, SDL_KMOD_CTRL);
    CHECK(strcmp(app->cmd, (std::string("rm ") + p.current_dir).c_str()) == 0);

    // A path longer than the buffer truncates instead of overflowing it.
    char deep[512];
    for (size_t i = 0; i < sizeof(deep) - 1; i++) deep[i] = 'x';
    deep[sizeof(deep) - 1] = '\0';
    snprintf(p.current_dir, sizeof(p.current_dir), "/%s", deep);
    app->cmd[0] = '\0';
    app_panes_handle_key(app, SDLK_P, SDL_KMOD_CTRL);
    CHECK(strlen(app->cmd) < sizeof(app->cmd));
    snprintf(p.current_dir, sizeof(p.current_dir), "%s", root.c_str());
    app->cmd[0] = '\0';

    // Ctrl+I moves the focus, it no longer touches the marks.
    refresh_pane(&p, root.c_str());
    clear_marks(p);
    int before = marked_count(p);
    bool was_left = app->left_focus;
    app_panes_handle_key(app, SDLK_I, SDL_KMOD_CTRL);
    CHECK(app->left_focus != was_left);
    CHECK(marked_count(p) == before);
    app_panes_handle_key(app, SDLK_I, SDL_KMOD_CTRL);
    CHECK(app->left_focus == was_left);

    // Num* still inverts, so nothing was lost by moving Ctrl+I. ".." is never
    // marked, so the count is one short of the row count.
    app_panes_handle_key(app, SDLK_ASTERISK, SDL_KMOD_NONE);
    CHECK(marked_count(p) == p.entry_count - 1);
    app_panes_handle_key(app, SDLK_ASTERISK, SDL_KMOD_NONE);
    CHECK(marked_count(p) == 0);

    refresh_pane(&p, root.c_str());
}

// The pack dialog is laid out by ImGui, so "does the text fit" is measurable
// without a display: render one frame and compare how far the content reached
// with the window's own right edge. Every format is checked because each one
// swaps in different hint and refusal text.
static void test_pack_dialog_layout(AppPanes* app) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    // ImGui would write its window layout to imgui.ini in the working directory
    // on Render(); a layout test has no layout to keep.
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(1280, 800);
    // No renderer in a headless test, so build the font atlas on the CPU: layout
    // needs glyph metrics, not a texture upload.
    unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
    io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);
    CHECK(fw > 0 && fh > 0);

    snprintf(app->pack_dir, sizeof(app->pack_dir),
             "/home/adam/documents/projects/work/quarterly-reports-and-forecasts/2026");
    snprintf(app->pack_name, sizeof(app->pack_name),
             "quarterly-report-final-revised-with-comments");
    app->pack_open = true;
    const std::vector<ArchKind>& kinds = arch_pack_kinds();
    for (int k = 0; k < (int)kinds.size(); k++) {
        app->pack_kind_idx = k;
        // A password on a format that cannot encrypt it puts the refusal text in
        // the dialog, so the refusal has to fit too.
        snprintf(app->pack_password, sizeof(app->pack_password), "hunter2");
        ImGui::NewFrame();
        render_pack_dialog(app);
        ImGui::Render();
        ImGuiWindow* w = ImGui::FindWindowByName("Pack into archive");
        CHECK(w != nullptr);
        if (!w) continue;
        float right = w->Pos.x + w->Size.x;
        if (w->DC.CursorMaxPos.x > right) {
            printf("pack dialog overflows for %s: content reaches %.0f, window ends at %.0f\n",
                   arch_kind_name(kinds[k]), w->DC.CursorMaxPos.x, right);
        }
        CHECK(w->DC.CursorMaxPos.x <= right + 0.5f);
    }

    // The elision keeps both ends, and only kicks in when it has to.
    snprintf(app->pack_dir, sizeof(app->pack_dir), "/tmp");
    ImGui::NewFrame();
    render_pack_dialog(app);
    ImGui::Render();
    ImGuiWindow* w = ImGui::FindWindowByName("Pack into archive");
    CHECK(w != nullptr);
    if (w) CHECK(w->DC.CursorMaxPos.x <= w->Pos.x + w->Size.x + 0.5f);

    ImGui::NewFrame();
    const char* deep = "/home/adam/documents/projects/work/quarterly-reports-and-forecasts/2026";
    CHECK(elide_middle(deep, 1e9f) == deep);            // fits untouched
    std::string cut = elide_middle(deep, 120.0f);
    CHECK(cut != deep);
    CHECK(ImGui::CalcTextSize(cut.c_str()).x <= 120.0f);
    // The head keeps the root of the path, the tail keeps the leaf name.
    if (!cut.starts_with("/home/adam") || !cut.ends_with("2026"))
        printf("elided to fit 120px: %s\n", cut.c_str());
    CHECK(cut.starts_with("/home/adam"));
    CHECK(cut.ends_with("2026"));
    CHECK(cut.find("...") != std::string::npos);
    ImGui::Render();

    app->pack_open = false;
    app->pack_password[0] = '\0';
    app->pack_kind_idx = 0;
    ImGui::DestroyContext(ctx);
}

// The deferred-action table. A menu item, a context-menu entry or a dialog
// button fires inside the ImGui frame, so it can only record a request; the
// operation itself runs between frames, in app_panes_run_pending(). A constant
// that falls through to the default case does nothing at all while the widget
// that set it still looks like it worked, so every constant is driven here and
// the effect it is supposed to have is checked on disk.
static void test_deferred_ops(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    Pane& q = app->right;
    app->left_focus = true;

    sh("rm -rf '" + root + "/defer'");
    sh("mkdir -p '" + root + "/defer/src' '" + root + "/defer/dst' "
       "'" + root + "/defer/paste' '" + root + "/defer/links' '" + root + "/defer/out'");
    touch_file(root + "/defer/src", "one.txt");
    touch_file(root + "/defer/src", "two.txt");
    {
        StringList names;
        names.push_back("one.txt");
        std::string err;
        CHECK(arch_pack((root + "/defer/pkg.zip").c_str(), (root + "/defer/src").c_str(),
                        names, nullptr, nullptr, &err));
    }

    // DEFER_COPY and DEFER_MOVE: the entry menu's two plain items.
    refresh_pane(&p, (root + "/defer/src").c_str());
    refresh_pane(&q, (root + "/defer/dst").c_str());
    p.selected = idx_of(p, "one.txt");
    CHECK(p.selected >= 0);
    app->pending_op = DEFER_COPY;
    app_panes_run_pending(app);
    CHECK(app->op == OP_COPY);          // the menu item opens the dialog, it does not copy
    accept_op(app);
    CHECK(app->op == OP_NONE);
    CHECK(fs_exists((root + "/defer/dst/one.txt").c_str()));
    CHECK(fs_exists((root + "/defer/src/one.txt").c_str()));   // a copy keeps the source

    p.selected = idx_of(p, "two.txt");
    CHECK(p.selected >= 0);
    app->pending_op = DEFER_MOVE;
    app_panes_run_pending(app);
    CHECK(app->op == OP_MOVE);
    accept_op(app);
    CHECK(fs_exists((root + "/defer/dst/two.txt").c_str()));
    CHECK(!fs_exists((root + "/defer/src/two.txt").c_str()));

    // The request is consumed, so the next frame does not run it a second time.
    CHECK(app->pending_op == DEFER_NONE);
    int rows = p.entry_count;
    app_panes_run_pending(app);
    CHECK(p.entry_count == rows);

    // DEFER_PASTE: the clipboard is the source and the focused pane is where it
    // lands, which is why both the Commands menu and "Paste here" defer.
    refresh_pane(&p, (root + "/defer/src").c_str());
    p.selected = idx_of(p, "one.txt");
    CHECK(p.selected >= 0);
    clipboard_set(app, p, false);
    CHECK(!app->clipboard.paths.empty());
    refresh_pane(&q, (root + "/defer/paste").c_str());
    app->left_focus = false;
    app->pending_op = DEFER_PASTE;
    app_panes_run_pending(app);
    CHECK(fs_exists((root + "/defer/paste/one.txt").c_str()));
    app->clipboard.paths.clear();
    app->left_focus = true;

    // DEFER_COPY_IN_PLACE (Shift+F5) and DEFER_SYMLINK_OTHER (Shift+Ctrl+F5).
    refresh_pane(&p, (root + "/defer/src").c_str());
    p.selected = idx_of(p, "one.txt");
    CHECK(p.selected >= 0);
    app->pending_op = DEFER_COPY_IN_PLACE;
    app_panes_run_pending(app);
    CHECK(fs_exists((root + "/defer/src/one.txt.copy").c_str()));

    refresh_pane(&q, (root + "/defer/links").c_str());
    p.selected = idx_of(p, "one.txt");
    CHECK(p.selected >= 0);
    app->pending_op = DEFER_SYMLINK_OTHER;
    app_panes_run_pending(app);
    struct stat st;
    CHECK(lstat((root + "/defer/links/one.txt").c_str(), &st) == 0 && S_ISLNK(st.st_mode));

    // DEFER_FILL_SIZES (Alt+Shift+Enter) fills the size column for directories.
    refresh_pane(&p, root.c_str());
    CHECK(p.dir_size[idx_of(p, "sub")] == -1);
    app->pending_op = DEFER_FILL_SIZES;
    app_panes_run_pending(app);
    CHECK(p.dir_size[idx_of(p, "sub")] >= 0);

    // DEFER_EXTRACT (Alt+F6 from the Commands menu) and DEFER_PACK (the Pack
    // button and Enter in the pack dialog). Both pump the progress UI, so both
    // have to arrive here rather than running inside the frame.
    refresh_pane(&p, (root + "/defer").c_str());
    refresh_pane(&q, (root + "/defer/out").c_str());
    p.selected = idx_of(p, "pkg.zip");
    CHECK(p.selected >= 0);
    app->pending_op = DEFER_EXTRACT;
    app_panes_run_pending(app);
    CHECK(fs_exists((root + "/defer/out/one.txt").c_str()));
    CHECK(strstr(app->status_msg, "Extracted") != NULL);

    refresh_pane(&p, (root + "/defer/src").c_str());
    for (int i = 0; i < p.entry_count; i++)
        if (strcmp(p.entries[i]->name, "..") != 0) p.marked[i] = true;
    do_pack(app, false);
    CHECK(app->pack_open);
    // The dialog keeps the last format chosen, so name one instead of trusting
    // what an earlier test left in the combo.
    app->pack_kind_idx = kind_idx(ARCH_ZIP);
    snprintf(app->pack_name, sizeof(app->pack_name), "deferred");
    app->pending_op = DEFER_PACK;
    app_panes_run_pending(app);
    CHECK(!app->pack_open);
    CHECK(fs_exists((root + "/defer/src/deferred.zip").c_str()));

    sh("rm -rf '" + root + "/defer'");
}

// The operation dialog. F7 puts a folder name in a field that already has the
// keyboard, F5 and F6 show where the operation is going and let that be changed,
// and nothing reaches the filesystem until Enter is pressed.
static void test_op_dialog(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    Pane& q = app->right;
    app->left_focus = true;
    app->cmd[0] = '\0';   // a leftover command line would make Enter run it
    refresh_pane(&p, root.c_str());
    refresh_pane(&q, root.c_str());
    p.selected = idx_of(p, "alpha.txt");

    // ---- F7: the dialog opens ready to type ----
    app_panes_handle_key(app, SDLK_F7, SDL_KMOD_NONE);
    CHECK(app->op == OP_MKDIR);
    CHECK(app->op_focus_request);          // the field takes the keyboard on the frame it opens
    CHECK(app->op_name[0] == '\0');
    app->op_focus_request = false;         // a real frame would have consumed it

    // Enter on an empty field is a mistake, not a request for a nameless folder.
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_MKDIR);            // the dialog stays up
    CHECK(app->op_error[0] != '\0');

    snprintf(app->op_name, sizeof(app->op_name), "made");
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(app->op == OP_NONE);
    CHECK(!fs_exists((root + "/made").c_str()));   // Esc really abandons the operation

    // And again, this time answered: Enter is the whole operation.
    app_panes_handle_key(app, SDLK_F7, SDL_KMOD_NONE);
    snprintf(app->op_name, sizeof(app->op_name), "made");
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_NONE);
    CHECK(fs_exists((root + "/made").c_str()));
    CHECK(strstr(app->status_msg, "Created") != NULL);

    // A name that cannot be taken keeps the dialog and the reason in it, so the
    // fix is typed in place instead of the whole operation being restarted.
    app_panes_handle_key(app, SDLK_F7, SDL_KMOD_NONE);
    snprintf(app->op_name, sizeof(app->op_name), "made");
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_MKDIR);
    CHECK(strstr(app->op_error, "Cannot create") != NULL);
    snprintf(app->op_name, sizeof(app->op_name), "made2");
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_NONE);
    CHECK(fs_exists((root + "/made2").c_str()));

    // The OK button only records the request; the run happens between frames.
    app_panes_handle_key(app, SDLK_F7, SDL_KMOD_NONE);
    snprintf(app->op_name, sizeof(app->op_name), "viabutton");
    app->pending_op = DEFER_OP_COMMIT;
    app_panes_run_pending(app);
    CHECK(app->op == OP_NONE);
    CHECK(fs_exists((root + "/viabutton").c_str()));
    sh("rmdir '" + root + "/made' '" + root + "/made2' '" + root + "/viabutton'");

    // While the dialog is up the arrows and Delete belong to the field: a long
    // typed path has to be editable, and Down must not walk the file list.
    int sel = p.selected;
    CHECK(app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));     // normally the pane's key
    app_panes_handle_key(app, SDLK_F7, SDL_KMOD_NONE);
    CHECK(!app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));    // now the field's
    CHECK(!app_key_is_special(SDLK_HOME, SDL_KMOD_NONE, app));
    app_panes_handle_key(app, SDLK_DOWN, SDL_KMOD_NONE);
    CHECK(p.selected == sel);              // the pane's cursor did not move
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));   // and back to normal after

    // ---- F5: the destination is shown, and it is what runs ----
    std::string dst = root + "/dst";
    sh("rm -rf '" + dst + "'");
    sh("mkdir -p '" + dst + "'");
    refresh_pane(&q, dst.c_str());
    refresh_pane(&p, root.c_str());
    p.selected = idx_of(p, "alpha.txt");
    CHECK(p.selected >= 0);
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    CHECK(app->op == OP_COPY);
    CHECK(app->op_plan.names.size() == 1);
    CHECK(strcmp(app->op_name, (dst + "/alpha.txt").c_str()) == 0);   // the whole target, prefilled
    CHECK(!fs_exists((dst + "/alpha.txt").c_str()));                  // nothing written yet

    // Renaming while copying is the same keystrokes as copying.
    snprintf(app->op_name, sizeof(app->op_name), "%s/renamed.txt", dst.c_str());
    accept_op(app);
    CHECK(fs_exists((dst + "/renamed.txt").c_str()));
    CHECK(!fs_exists((dst + "/alpha.txt").c_str()));
    CHECK(strstr(app->status_msg, "Copied 1 item to") != NULL);
    // The pane that is looking at the destination shows what landed there, so
    // the result of the operation is visible without a manual refresh.
    CHECK(idx_of(q, "renamed.txt") >= 0);

    // Several items have to land in a directory: a name would silently drop one.
    refresh_pane(&p, root.c_str());
    p.marked[idx_of(p, "alpha.txt")] = true;
    p.marked[idx_of(p, "beta.txt")] = true;
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    CHECK(app->op_plan.names.size() == 2);
    CHECK(strcmp(app->op_name, dst.c_str()) == 0);       // several: the field is the directory
    snprintf(app->op_name, sizeof(app->op_name), "%s/both.txt", dst.c_str());
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_COPY);
    CHECK(strstr(app->op_error, "has to be a directory") != NULL);
    CHECK(!fs_exists((dst + "/both.txt").c_str()));
    for (int i = 0; i < p.entry_count; i++) p.marked[i] = false;
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(app->op == OP_NONE);

    // A destination whose folder is missing is refused: a typo in a typed path
    // must not quietly create a second one. The trailing slash is what says a
    // folder is meant, and then making it is the whole point.
    refresh_pane(&p, root.c_str());
    p.selected = idx_of(p, "gamma.log");
    CHECK(p.selected >= 0);
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    snprintf(app->op_name, sizeof(app->op_name), "%s/nosuch/gamma.log", dst.c_str());
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_COPY);
    CHECK(strstr(app->op_error, "no directory") != NULL);
    CHECK(!fs_exists((dst + "/nosuch").c_str()));
    snprintf(app->op_name, sizeof(app->op_name), "%s/made/sub/", dst.c_str());
    accept_op(app);
    CHECK(app->op == OP_NONE);
    CHECK(fs_exists((dst + "/made/sub/gamma.log").c_str()));

    // Copying a file onto itself is refused: the copy opens the target for
    // writing before it reads the source, so the file would be lost.
    refresh_pane(&q, root.c_str());
    refresh_pane(&p, root.c_str());
    p.selected = idx_of(p, "alpha.txt");
    CHECK(p.selected >= 0);
    app_panes_handle_key(app, SDLK_F5, SDL_KMOD_NONE);
    CHECK(strcmp(app->op_name, (root + "/alpha.txt").c_str()) == 0);
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_COPY);
    CHECK(strstr(app->op_error, "is already there") != NULL);
    CHECK(fs_exists((root + "/alpha.txt").c_str()));
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);

    // The dialog is authoritative. It renames the entry on its own "Renaming:"
    // line, so marks and a click on the other pane cannot move the operation
    // underneath it while it is open.
    refresh_pane(&p, root.c_str());
    p.selected = idx_of(p, "gamma.log");
    CHECK(p.selected >= 0);
    p.marked[idx_of(p, "alpha.txt")] = true;
    app_panes_handle_key(app, SDLK_F2, SDL_KMOD_NONE);
    CHECK(app->op == OP_RENAME);
    CHECK(strcmp(app->op_name, "gamma.log") == 0);
    app->left_focus = false;                 // as if the other pane had been clicked
    snprintf(app->op_name, sizeof(app->op_name), "gamma2.log");
    accept_op(app);
    CHECK(fs_exists((root + "/gamma2.log").c_str()));
    CHECK(fs_exists((root + "/alpha.txt").c_str()));   // the marked entry keeps its own name
    app->left_focus = true;
    for (int i = 0; i < p.entry_count; i++) p.marked[i] = false;
    sh("mv '" + root + "/gamma2.log' '" + root + "/gamma.log'");

    // ---- F6: the same dialog, moving ----
    refresh_pane(&p, root.c_str());
    p.selected = idx_of(p, "beta.txt");
    CHECK(p.selected >= 0);
    app_panes_handle_key(app, SDLK_F6, SDL_KMOD_NONE);
    CHECK(app->op == OP_MOVE);
    snprintf(app->op_name, sizeof(app->op_name), "%s/beta2.txt", root.c_str());
    accept_op(app);
    CHECK(!fs_exists((root + "/beta.txt").c_str()));
    CHECK(fs_exists((root + "/beta2.txt").c_str()));
    CHECK(strstr(app->status_msg, "Moved 1 item to") != NULL);
    // The source pane lost the row and the cursor stayed in the list rather than
    // running off the end of it.
    CHECK(idx_of(p, "beta.txt") < 0);
    CHECK(p.selected >= 0 && p.selected < p.entry_count);
    // And the pane looking at the destination gained it.
    CHECK(idx_of(q, "beta2.txt") >= 0);
    sh("mv '" + root + "/beta2.txt' '" + root + "/beta.txt'");
    sh("rm -rf '" + dst + "'");
}

// Both panes render into the same ImGui window, so a label used by both sides is
// the same item twice. ImGui only notices while the mouse is over one of them: it
// counts the items whose ID equals the ID hovered in the previous frame, and more
// than one raises its "visible items with conflicting ID" error box. Sweeping the
// mouse over the window and reading that counter is therefore a real test and not
// a restatement of the fix - it caught the tab strip, where the add-tab "+" and
// every tab label were pushed with the same ID on both sides. The 12px step is
// coarse enough to stay under a second and fine enough to land on a small button.
static void test_ui_id_uniqueness(AppPanes* app) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(1280, 800);
    unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
    io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);

    int conflicts = 0;
    // The transfer strip is the one part of this frame whose row count changes
    // while the app runs, so it is scanned with the panes instead of assumed
    // safe. One running row and one finished row put both the progress bar and
    // the button in the frame, and the strip takes room the panes then lose.
    for (int i = 0; i < 2; i++) {
        std::unique_ptr<BgTransfer> up = std::make_unique<BgTransfer>();
        BgTransfer* t = up.get();
        t->state = i == 0 ? BgTransfer::BG_RUNNING : BgTransfer::BG_DONE;
        t->abort = t->settled = t->dismiss = false;
        t->done = 3000000;
        t->total = 9000000;
        t->files_done = 1;
        t->files_total = 4;
        t->is_move = i == 1;
        t->download = true;
        t->t0 = SDL_GetTicks() / 1000.0 - 6.0;
        t->src = "ftp://files.example.org/pub/IDA Pro 9.6.261001";
        t->dst = "/home/adam/Downloads/IDA Pro 9.6.261001";
        app->transfers.push_back(std::move(up));
    }
    CHECK(bg_strip_height(app, ImGui::GetTextLineHeight()) > 0.0f);

    for (int y = 8; y < 800 && conflicts < 3; y += 12) {
        for (int x = 4; x < 1280 && conflicts < 3; x += 12) {
            io.MousePos = ImVec2((float)x, (float)y);
            // Two frames: the first sets the hovered ID, the second is where
            // ImGui counts the items that answer to it.
            for (int f = 0; f < 2; f++) {
                ImGui::NewFrame();
                app_panes_render(app);
                ImGui::Render();
                if (ctx->DebugDrawIdConflictsId != 0) {
                    printf("duplicate item ID %08X under the mouse at %d,%d\n",
                           ctx->DebugDrawIdConflictsId, x, y);
                    conflicts++;
                }
            }
        }
    }
    io.MousePos = ImVec2(-FLT_MAX, -FLT_MAX);
    CHECK(conflicts == 0);
    app->transfers.clear();
    ImGui::DestroyContext(ctx);
}

// The font tree: which files count as fonts, how deep and how wide the scan
// goes, and what it never does twice.
static void test_font_scan(const std::string& root) {
    sh("mkdir -p '" + root + "/fonts/DejaVu' '" + root + "/fonts/.local-cache' '" +
       root + "/fonts/deep/deeper/deepest' '" + root + "/fonts/loose'");
    sh("touch '" + root + "/fonts/DejaVu/DejaVuSans.ttf'"
       " '" + root + "/fonts/DejaVu/DejaVuSans-Bold.otf'"
       " '" + root + "/fonts/DejaVu/notes.txt'"
       " '" + root + "/fonts/DejaVu/collection.ttc'"
       " '" + root + "/fonts/DejaVu/UPPERCASE.TTF'"
       " '" + root + "/fonts/.local-cache/hidden.ttf'"
       " '" + root + "/fonts/deep/deeper/deepest/buried.ttf'"
       " '" + root + "/fonts/loose/one.ttf'");

    StringList out;
    scan_font_tree((root + "/fonts").c_str(), out, 6, 400);

    bool has_ttf = false, has_otf = false, has_ttc = false, has_upper = false;
    for (const std::string& s : out) {
        if (s == root + "/fonts/DejaVu/DejaVuSans.ttf") has_ttf = true;
        if (s == root + "/fonts/DejaVu/DejaVuSans-Bold.otf") has_otf = true;
        if (s == root + "/fonts/DejaVu/collection.ttc") has_ttc = true;
        if (s == root + "/fonts/DejaVu/UPPERCASE.TTF") has_upper = true;
        CHECK(s.find("/notes.txt") == std::string::npos);   // not a font extension
        CHECK(s.find("/.local-cache") == std::string::npos); // a dot directory is not searched
    }
    CHECK(has_ttf && has_otf && has_ttc && has_upper);      // .TTF counts as well as .ttf

    // Depth is a real limit: a font six levels down is not in a shallow scan.
    StringList shallow;
    scan_font_tree((root + "/fonts").c_str(), shallow, 1, 400);
    for (const std::string& s : shallow)
        CHECK(s.find("buried.ttf") == std::string::npos);
    bool buried = false;
    for (const std::string& s : out) if (s.find("buried.ttf") != std::string::npos) buried = true;
    CHECK(buried);

    // The cap holds, because the list is drawn in a dialog and not in a pager.
    StringList capped;
    scan_font_tree((root + "/fonts").c_str(), capped, 6, 2);
    CHECK((int)capped.size() <= 2);

    // Scanning the same tree twice into the same list does not double the rows.
    size_t before = out.size();
    scan_font_tree((root + "/fonts").c_str(), out, 6, 400);
    CHECK(out.size() == before);

    // The real scan: on a machine with fonts installed it finds some, and the
    // list is ordered by file name, which is what the picker is read by.
    StringList sys;
    app_scan_fonts(sys);
    if (fs_exists("/usr/share/fonts")) {
        CHECK(!sys.empty());
        for (size_t i = 1; i < sys.size(); i++)
            CHECK(strcasecmp(file_base(sys[i - 1].c_str()), file_base(sys[i].c_str())) <= 0);
    }
    for (const std::string& s : sys)
        CHECK(s.find(root) == std::string::npos);   // the temp tree is not a font directory

    // The filter is a substring box, case-insensitive: "dejavu" means DejaVuSans.
    CHECK(icontains("/usr/share/fonts/TTF/DejaVuSans-Bold.ttf", "dejavu"));
    CHECK(icontains("DejaVuSans-Bold.ttf", "BOLD.TTF"));
    CHECK(!icontains("DejaVuSans.ttf", "adwaita"));
    CHECK(icontains("anything", ""));
}

// A font is applied between frames, and a font that cannot be read is not left
// in the settings: the built-in font goes back in and the dialog says so.
static void test_font_apply(AppPanes* app, const std::string& root) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGui::GetIO().IniFilename = nullptr;

    sh("mkdir -p '" + root + "/badfonts'");
    sh("printf 'not a font at all' > '" + root + "/badfonts/fake.ttf'");
    sh("head -c 400 /dev/zero > '" + root + "/badfonts/bigjunk.ttf'");

    // A file too small to be a font: ImGui would assert on it, so it is refused
    // before the atlas is touched.
    snprintf(app->font, sizeof(app->font), "%s/badfonts/fake.ttf", root.c_str());
    app->font_size = 18.0f;
    app->font_msg[0] = '\0';
    app_panes_apply_font(app);
    CHECK(app->font[0] == '\0');                       // the unreadable path is dropped
    CHECK(app->font_msg[0] != '\0');                   // and there is something to show
    CHECK(strstr(app->font_msg, "built-in") != NULL);
    CHECK(!app->font_dirty);
    // Text is still drawable: an empty atlas would blank the whole UI.
    CHECK(ImGui::GetIO().Fonts->Fonts.Size > 0);

    // A file big enough to try but not a font: the loader refuses it and the
    // built-in font goes back in.
    snprintf(app->font, sizeof(app->font), "%s/badfonts/bigjunk.ttf", root.c_str());
    CHECK(!app_font_apply(app->font, 18.0f, "default"));
    CHECK(ImGui::GetIO().Fonts->Fonts.Size > 0);

    // A path that does not exist at all.
    CHECK(!app_font_apply("/nonexistent/no-such-font.ttf", 18.0f, "default"));

    // A real font, when this machine has one.
    StringList fonts;
    app_scan_fonts(fonts);
    if (!fonts.empty()) {
        snprintf(app->font, sizeof(app->font), "%s", fonts[0].c_str());
        app->font_size = 20.0f;
        app_panes_apply_font(app);
        CHECK(app->font[0] != '\0');                   // the pick is kept
        CHECK(strstr(app->font_msg, "20 px") != NULL);
        CHECK(ImGui::GetIO().Fonts->Fonts.Size > 0);
    }

    // The built-in font at a size scales instead of failing, and 0 px puts the
    // built-in size back.
    app->font[0] = '\0';
    app->font_size = 20.0f;
    CHECK(app_font_apply(app->font, app->font_size, app->hinting));
    CHECK(ImGui::GetStyle().FontScaleMain > 1.4f);
    app->font_size = 0.0f;
    CHECK(app_font_apply(app->font, app->font_size, app->hinting));
    CHECK(ImGui::GetStyle().FontScaleMain == 1.0f);

    ImGui::DestroyContext(ctx);
}

// The size has to reach the pixels. For a TrueType font it used to stop short of
// them: the size handed to AddFont() only seeds style.FontSizeBase, which ImGui
// reads once on the first frame, so moving the slider rebuilt the atlas and left
// the text exactly as tall as it was. ImGui::GetFontSize() inside a frame is the
// height the UI actually draws at, so that is what is measured - for both fonts,
// and for a change made after that first frame.
static float rendered_font_size() {
    // This build has no texture backend, so the atlas has to be built by hand
    // before a frame - which also forces the glyphs to be rasterized at the size
    // the frame is about to draw at.
    ImU8* px = nullptr; int w = 0, h = 0;
    ImGui::GetIO().Fonts->GetTexDataAsRGBA32(&px, &w, &h);
    ImGui::NewFrame();
    ImGui::Begin("size probe");
    float fs = ImGui::GetFontSize();
    ImGui::End();
    ImGui::Render();
    return fs;
}

static void test_font_size() {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(800, 600);

    // The built-in font: the number in the dialog is the height it draws at.
    CHECK(app_font_apply(nullptr, 0.0f, "default"));
    CHECK(rendered_font_size() == 13.0f);        // 0 px is the built-in size
    CHECK(app_font_apply(nullptr, 20.0f, "default"));
    CHECK(rendered_font_size() == 20.0f);
    CHECK(app_font_apply(nullptr, 0.0f, "default"));
    CHECK(rendered_font_size() == 13.0f);        // and 0 px puts it back

    StringList fonts;
    app_scan_fonts(fonts);
    if (fonts.empty()) { ImGui::DestroyContext(ctx); return; }   // nothing to measure here

    // A TrueType file resized after the first frame: the case that was broken.
    CHECK(app_font_apply(fonts[0].c_str(), 13.0f, "default"));
    CHECK(rendered_font_size() == 13.0f);        // the frame that seeds the base size
    CHECK(app_font_apply(fonts[0].c_str(), 24.0f, "default"));
    CHECK(rendered_font_size() == 24.0f);
    CHECK(app_font_apply(fonts[0].c_str(), 13.0f, "default"));
    CHECK(rendered_font_size() == 13.0f);

    // One number, either font.
    CHECK(app_font_apply(nullptr, 18.0f, "default"));
    float builtin = rendered_font_size();
    CHECK(app_font_apply(fonts[0].c_str(), 18.0f, "default"));
    CHECK(rendered_font_size() == builtin);

    // And the glyphs really are that tall. A scale that moved the metrics but not
    // the raster would satisfy every check above and still show 13 px text.
    CHECK(app_font_apply(fonts[0].c_str(), 30.0f, "default"));
    ImFontBaked* big = io.Fonts->Fonts[0]->GetFontBaked(30.0f);
    CHECK(big != nullptr);
    if (big) {
        CHECK(big->Size == 30.0f);
        ImFontGlyph* h = big->FindGlyph('H');
        CHECK(h != nullptr);
        if (h) CHECK(h->Y1 - h->Y0 > 12.0f);     // an H most of 30 px, not of 13
    }
    ImGui::DestroyContext(ctx);
}

// Hinting is a named setting with a real effect on the pixels, so the parts that
// can drift are each pinned down: the names round-trip through the config, the
// translation to the loader is the one FreeType documents, every mode survives a
// real font, and the loader is actually installed rather than merely available.
// A build without FreeType has the vocabulary but nothing to honour it, and says
// which rasterizer it has instead of pretending otherwise.
static void test_hinting(AppPanes* app, const std::string& root) {
    int n = 0;
    const char* const* names = mc_hinting_list(&n);
    CHECK(n > 0);
    for (int i = 0; i < n; i++) {
        CHECK(names[i][0] != '\0');
        CHECK(mc_hinting_index(names[i]) == i);   // the picker's row is the config's name
    }
    CHECK(mc_hinting_index("ultra-crisp") == -1); // a hand-edited config is not guessed at
    CHECK(mc_hinting_index("") == -1);
    CHECK(mc_hinting_index(NULL) == -1);

    // Each mode asks for something different, and "default" asks for nothing:
    // it is the loader's own choice, not an invention of this app.
    unsigned int f_def  = mc_freetype_loader_flags("default");
    unsigned int f_none = mc_freetype_loader_flags("none");
    unsigned int f_lite = mc_freetype_loader_flags("light");
    unsigned int f_mono = mc_freetype_loader_flags("mono");
    unsigned int f_hard = mc_freetype_loader_flags("mono (no smoothing)");
    CHECK(f_def == 0);
    CHECK(f_none != f_def && f_lite != f_def && f_mono != f_def);
    CHECK(f_lite != f_mono && f_mono != f_hard && f_none != f_hard);
    // An unknown name falls back to that same default rather than to a random bit.
    CHECK(mc_freetype_loader_flags("ultra-crisp") == f_def);
    CHECK(mc_freetype_loader_flags(NULL) == f_def);
#ifdef MC_HAVE_FREETYPE
    CHECK(f_none == (unsigned int)ImGuiFreeTypeLoaderFlags_NoHinting);
    CHECK(f_lite == (unsigned int)ImGuiFreeTypeLoaderFlags_LightHinting);
    CHECK(f_mono == (unsigned int)ImGuiFreeTypeLoaderFlags_MonoHinting);
    CHECK(f_hard == (unsigned int)(ImGuiFreeTypeLoaderFlags_MonoHinting |
                                   ImGuiFreeTypeLoaderFlags_Monochrome));
#endif

    char raster[64];
    mc_font_rasterizer(raster, sizeof(raster));
    CHECK(raster[0] != '\0');
#ifdef MC_HAVE_FREETYPE
    CHECK(mc_font_hinting_available());
    CHECK(strstr(raster, "FreeType") == raster);   // named, with a version to look up
#else
    CHECK(!mc_font_hinting_available());
    CHECK(!strcmp(raster, "stb_truetype"));
#endif

    // The setting survives a session, and a name this build does not know is
    // dropped on the way back in instead of being reinterpreted.
    MCConfig cfg;
    mc_config_default(&cfg);
    CHECK(!strcmp(cfg.hinting, "default"));
    snprintf(app->hinting, sizeof(app->hinting), "mono");
    app_panes_save_state(app, &cfg);
    CHECK(!strcmp(cfg.hinting, "mono"));
    AppPanes next;
    app_panes_apply_state(&next, &cfg);
    CHECK(!strcmp(next.hinting, "mono"));

    snprintf(cfg.hinting, sizeof(cfg.hinting), "ultra-crisp");
    snprintf(next.hinting, sizeof(next.hinting), "default");
    app_panes_apply_state(&next, &cfg);
    CHECK(!strcmp(next.hinting, "default"));
    cfg.hinting[0] = '\0';
    app_panes_apply_state(&next, &cfg);
    CHECK(!strcmp(next.hinting, "default"));
    snprintf(app->hinting, sizeof(app->hinting), "default");

    // Now the pixels. Every mode has to survive a real atlas rebuild, and with
    // FreeType the atlas has to answer to FreeType - an atlas still on
    // stb_truetype would ignore every mode below, and this test would pass while
    // the setting did nothing at all.
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    app_font_apply(nullptr, 0.0f, "default");
#ifdef MC_HAVE_FREETYPE
    CHECK(io.Fonts->FontLoader == ImGuiFreeType::GetFontLoader());
#endif

    StringList fonts;
    app_scan_fonts(fonts);
    const char* file = fonts.empty() ? nullptr : fonts[0].c_str();
    for (int i = 0; i < n; i++) {
        CHECK(app_font_apply(nullptr, 0.0f, names[i]));
        CHECK(io.Fonts->Fonts.Size > 0);
        // The mode reached the loader, not just the settings.
#ifdef MC_HAVE_FREETYPE
        CHECK(io.Fonts->FontLoaderFlags == mc_freetype_loader_flags(names[i]));
#endif
        // Force the rasterization: a mode the loader cannot combine with a real
        // face is a failure waiting for a click, and it shows up here as glyphs
        // that never get baked.
        ImFontBaked* baked = io.Fonts->Fonts[0]->GetFontBaked(18.0f);
        CHECK(baked != nullptr);
        if (!file) continue;
        CHECK(app_font_apply(file, 18.0f, names[i]));
        CHECK(io.Fonts->Fonts.Size > 0);
        ImFontBaked* fb = io.Fonts->Fonts[0]->GetFontBaked(18.0f);
        CHECK(fb != nullptr);
        if (fb) CHECK(fb->Size > 0.0f);
    }

#ifdef MC_HAVE_FREETYPE
    // And the flag reaches FreeType instead of being stored and ignored: the same
    // face at the same size lands on different pixels under "none" and under
    // "mono". Geometry is what hinting moves - corners and advance, snapped to the
    // grid or not - so geometry is what is compared. Without this check a loader
    // that quietly dropped the flags would pass every assertion above.
    if (file) {
        const char* pair[] = { "none", "mono" };
        const char* glyphs[] = { "A", "i", "m", "8", "o" };
        float before[5][3], after[5][3];
        memset(before, 0, sizeof(before));
        memset(after, 0, sizeof(after));
        for (int pass = 0; pass < 2; pass++) {
            CHECK(app_font_apply(file, 18.0f, pair[pass]));
            ImFontBaked* b = io.Fonts->Fonts[0]->GetFontBaked(18.0f);
            CHECK(b != nullptr);
            if (!b) break;
            for (int g = 0; g < 5; g++) {
                ImFontGlyph* gl = b->FindGlyph((ImWchar)glyphs[g][0]);
                if (!gl) continue;
                (pass ? after : before)[g][0] = gl->X0;
                (pass ? after : before)[g][1] = gl->X1;
                (pass ? after : before)[g][2] = gl->AdvanceX;
            }
        }
        bool moved = false;
        for (int g = 0; g < 5; g++)
            for (int k = 0; k < 3; k++)
                if (before[g][k] != after[g][k]) moved = true;
        CHECK(moved);       // hinting put the glyphs somewhere else on the grid
    }
#endif
    ImGui::DestroyContext(ctx);
}

// The density the glyphs are baked at is a measured property of the window, not a
// preference: it changes when the window moves to another monitor, and every
// glyph on screen is then wrong until the atlas is rebuilt.
static void test_display_scale() {
    AppPanes a;
    CHECK(a.display_scale == 1.0f);

    CHECK(app_panes_set_display_scale(&a, 2.0f));    // moved to a 2x display
    CHECK(a.display_scale == 2.0f);
    CHECK(a.font_dirty);                             // the rebuild is queued, not done here

    a.font_dirty = false;                            // main.cpp applied it between frames
    CHECK(!app_panes_set_display_scale(&a, 2.0f));   // the same scale is not an event
    CHECK(!a.font_dirty);

    CHECK(app_panes_set_display_scale(&a, 1.25f));   // desktop scaling changed
    CHECK(a.display_scale == 1.25f);
    CHECK(app_panes_set_display_scale(&a, 0.0f));    // nonsense clamps instead of dividing by it
    CHECK(a.display_scale == 1.0f);
}

// The density is derived from two measurements SDL makes about the window, and
// the derivation has to agree with what ImGui's SDL3 backend writes into
// io.DisplayFramebufferScale.x, because that is what the glyphs are baked at.
static void test_framebuffer_scale() {
    CHECK(mc_framebuffer_scale(1200, 2400) == 2.0f);   // a 2x display
    CHECK(mc_framebuffer_scale(1200, 1200) == 1.0f);   // a 1x display
    CHECK(mc_framebuffer_scale(1280, 1600) == 1.25f);  // 125% desktop scaling
    CHECK(mc_framebuffer_scale(1200, 3600) == 3.0f);   // a 3x display
    // A minimized window reports no logical size, and a mode change can report a
    // pixel size before the logical one. Neither is a scale of zero: text would be
    // baked at zero size and the screen would go blank.
    CHECK(mc_framebuffer_scale(0, 2400) == 1.0f);
    CHECK(mc_framebuffer_scale(1200, 0) == 1.0f);
    CHECK(mc_framebuffer_scale(-1200, -2400) == 1.0f);
}

// Who the build says it is, in one line for a terminal and in a block for the
// About window.
static void test_identity(AppPanes* app) {
    char line[256];
    app_identity_line(line, sizeof(line));
    CHECK(!strncmp(line, MC_APP_NAME, strlen(MC_APP_NAME)));   // the name leads
    CHECK(strstr(line, MC_VERSION) != NULL);
    CHECK(strstr(line, MC_APP_BINARY) != NULL);
    CHECK(strchr(line, '\n') == NULL);                         // one line, for --version
    CHECK(strlen(line) < 80);

    char about[2048];
    app_about_identity(about, sizeof(about));
    CHECK(strstr(about, MC_APP_NAME) != NULL);
    CHECK(strstr(about, MC_VERSION) != NULL);
    CHECK(strstr(about, MC_APP_BINARY) != NULL);
    CHECK(strstr(about, "Dear ImGui") != NULL);
    CHECK(strstr(about, "settings ") != NULL);
    CHECK(strstr(about, "rasterized with ") != NULL);   // which loader this build has
    CHECK(strstr(about, "archive tools found: ") != NULL);
    // The credit line lives in the same measured block as the rest of the header,
    // so the About window shows one paragraph instead of a name typed into the
    // widget beside it.
    CHECK(strstr(about, "Peter Garba") != NULL);
    // The About window is a paragraph, not a wall: it stays inside its buffer.
    CHECK(strlen(about) < sizeof(about) - 1);

    // The config path is the one the config was actually read from.
    char cfgp[1024];
    mc_config_path(cfgp, sizeof(cfgp));
    CHECK(strstr(cfgp, "mc-clone") != NULL);
    CHECK(strlen(cfgp) < sizeof(cfgp) - 1);
}

// The title bar: the app's name, then where the active pane is looking. Long
// paths lose their middle, never their last component, because the last
// component is the one that identifies the directory.
static void test_title(AppPanes* app) {
    char title[512];

    snprintf(app->left.current_dir, sizeof(app->left.current_dir), "/home/adam/github/immc");
    snprintf(app->right.current_dir, sizeof(app->right.current_dir), "/var/log");

    app->left_focus = true;
    app_window_title(app, title, sizeof(title));
    CHECK(!strcmp(title, "immc - /home/adam/github/immc"));

    // The active pane, not the other one.
    app->left_focus = false;
    app_window_title(app, title, sizeof(title));
    CHECK(!strcmp(title, "immc - /var/log"));
    app->left_focus = true;

    // An archive's virtual path shows the archive it belongs to.
    snprintf(app->left.current_dir, sizeof(app->left.current_dir),
             "/data/backup.tar.gz/packages/kernel");
    app_window_title(app, title, sizeof(title));
    CHECK(strstr(title, "backup.tar.gz") != NULL);
    snprintf(app->left.current_dir, sizeof(app->left.current_dir), "/home/adam/github/immc");

    // A deep path: the head and the leaf survive, the middle goes.
    std::string deep = "/home/adam";
    for (int i = 0; i < 40; i++) deep += "/a-deeply-nested-directory-of-some-sort";
    snprintf(app->left.current_dir, sizeof(app->left.current_dir), "%s", deep.c_str());
    app_window_title(app, title, sizeof(title));
    CHECK(!strncmp(title, "immc - /home/adam", strlen("immc - /home/adam")));
    CHECK(strstr(title, "...") != NULL);
    CHECK(!strcmp(title + strlen(title) - strlen("a-deeply-nested-directory-of-some-sort"),
                  "a-deeply-nested-directory-of-some-sort"));
    CHECK(strlen(title) <= strlen("immc - ") + MC_TITLE_MAX + 3);

    // A single component longer than the whole budget still shows its end.
    std::string huge = "/tmp/";
    for (int i = 0; i < 500; i++) huge += 'x';
    snprintf(app->left.current_dir, sizeof(app->left.current_dir), "%s", huge.c_str());
    app_window_title(app, title, sizeof(title));
    CHECK(strlen(title) <= strlen("immc - ") + MC_TITLE_MAX + 3);
    CHECK(strstr(title, huge.substr(huge.size() - 40).c_str()) != NULL);

    // A root directory is not elided into nothing.
    snprintf(app->left.current_dir, sizeof(app->left.current_dir), "/");
    app_window_title(app, title, sizeof(title));
    CHECK(!strcmp(title, "immc - /"));
}

// What the Options dialog changes has to survive the session: the same three
// fields the dialog writes are the three the next startup reads.
static void test_options_config(AppPanes* app) {
    MCConfig cfg;
    mc_config_default(&cfg);
    snprintf(app->theme, sizeof(app->theme), "gruvbox");
    snprintf(app->font, sizeof(app->font), "/usr/share/fonts/TTF/DejaVuSansMono.ttf");
    app->font_size = 17.0f;
    app_panes_save_state(app, &cfg);
    CHECK(!strcmp(cfg.theme, "gruvbox"));
    CHECK(!strcmp(cfg.font, "/usr/share/fonts/TTF/DejaVuSansMono.ttf"));
    CHECK(cfg.font_size == 17.0f);

    AppPanes next;
    app_panes_apply_state(&next, &cfg);
    CHECK(!strcmp(next.theme, "gruvbox"));
    CHECK(!strcmp(next.font, "/usr/share/fonts/TTF/DejaVuSansMono.ttf"));
    CHECK(next.font_size == 17.0f);

    // The F3 window's size travels the same way. ImGui's own window .ini is off,
    // so the config is the only thing that remembers how big the user made it.
    // The default the config writes and the default an app starts with have to be
    // the same window, or a config from before these keys existed opens something
    // else than the one the user first saw.
    AppPanes fresh;
    CHECK(cfg.qv_w == (int)fresh.qv_w && cfg.qv_h == (int)fresh.qv_h);
    app->qv_w = 900.0f;
    app->qv_h = 640.0f;
    app_panes_save_state(app, &cfg);
    CHECK(cfg.qv_w == 900 && cfg.qv_h == 640);
    app_panes_apply_state(&next, &cfg);
    CHECK(next.qv_w == 900.0f && next.qv_h == 640.0f);
    // A zero from a hand-edited config leaves the size that is already there
    // rather than opening a window with no room for a line of text.
    cfg.qv_w = 0; cfg.qv_h = 0;
    app_panes_apply_state(&next, &cfg);
    CHECK(next.qv_w == 900.0f && next.qv_h == 640.0f);

    // A config with no font means the built-in font at its own size.
    mc_config_default(&cfg);
    app_panes_apply_state(&next, &cfg);
    CHECK(next.font[0] == '\0');
    CHECK(next.font_size == 0.0f);

    // The theme list the picker is built from is the list the theme setter
    // accepts, and it is not empty.
    int n = 0;
    const char* const* names = mc_theme_list(&n);
    CHECK(n > 0);
    for (int i = 0; i < n; i++) CHECK(fs_exists(names[i]) == false || names[i][0] != '\0');
}

// The keys have to survive the file, not just the struct: the next run reads what
// this one wrote, and a key that does not match what the parser looks for is a
// setting that quietly stops being remembered. HOME points at a scratch tree for
// the duration and goes back before anything else can ask for it.
static void test_config_file(const std::string& root) {
    const char* real_home = getenv("HOME");
    std::string home = root + "/cfg-home";
    mkdir(home.c_str(), 0755);
    setenv("HOME", home.c_str(), 1);

    MCConfig cfg;
    mc_config_default(&cfg);
    cfg.qv_w = 900; cfg.qv_h = 640;
    mc_config_save(&cfg);

    MCConfig back;
    mc_config_default(&back);
    mc_config_load(&back);
    CHECK(back.qv_w == 900 && back.qv_h == 640);
    CHECK(back.win_w == 1280 && back.win_h == 800);   // the neighbours still parse

    // A size hand-edited too small to use is not loaded. The file is written by
    // this app, so anything in that field arrived by hand, and a window with no
    // room for a line of text is hard to drag back by its title bar.
    FILE* f = fopen((home + "/.config/mc-clone/config").c_str(), "a");
    if (f) { fprintf(f, "quickview_w = 5\nquickview_h = 7\n"); fclose(f); }
    mc_config_default(&back);
    mc_config_load(&back);
    CHECK(back.qv_w == 720 && back.qv_h == 460);

    if (real_home) setenv("HOME", real_home, 1); else unsetenv("HOME");
}

// A session that ended on a site or inside an archive has to come back to the
// same place. Both of those tab paths are virtual - "ftp://host/dir" and
// "pkg.zip/inner" are not names the filesystem has - so a restore that asks
// stat() about them throws the tab away, leaves the pane on the startup
// directory, and turns the copy the user starts there into an ordinary local one.
static void test_tab_restore(AppPanes* app, const std::string& root) {
    MCConfig cfg;
    mc_config_default(&cfg);

    snprintf(cfg.left_tabs[0], 4096, "%s", (root + "/sub").c_str());
    snprintf(cfg.left_tabs[1], 4096, "ftp://someone@example.com:2121/pub");
    cfg.left_tab_count = 2;
    cfg.left_tab_active = 1;

    snprintf(cfg.right_tabs[0], 4096, "%s", (root + "/gone").c_str());
    snprintf(cfg.right_tabs[1], 4096, "%s", (root + "/pkg.zip/sub").c_str());
    cfg.right_tab_count = 2;
    cfg.right_tab_active = 1;

    AppPanes next;
    net_bind(&next);              // app_panes_init() does this before restoring
    app_panes_apply_state(&next, &cfg);

    // The site tab survived and the pane is a remote pane pointing at it. There
    // is no saved login for it, which is a note in the status line, not a reason
    // to lose where the user was.
    CHECK(next.left.tab_count == 2);
    CHECK(next.left.tab_active == 1);
    CHECK(!strcmp(next.left.current_dir, "ftp://someone@example.com:2121/pub"));
    CHECK(in_remote(next.left));
    CHECK(!strcmp(next.left.remote_root, "ftp://someone@example.com:2121"));
    CHECK(!strcmp(next.left.remote_path, "/pub"));

    // A plain directory that went away is still dropped, and the archive tab that
    // took its place is the one showing, opened at the level it was left at.
    CHECK(next.right.tab_count == 1);
    CHECK(next.right.tab_active == 0);
    CHECK(in_archive(next.right));
    CHECK(!strcmp(next.right.archive_path, (root + "/pkg.zip").c_str()));
    CHECK(!strcmp(next.right.archive_prefix, "sub"));

    // An archive whose file is gone is dead like any other dead path, and a pane
    // with nothing left to restore is left alone.
    mc_config_default(&cfg);
    snprintf(cfg.right_tabs[0], 4096, "%s", (root + "/nothing.zip/sub").c_str());
    cfg.right_tab_count = 1;
    cfg.right_tab_active = 0;
    AppPanes third;
    net_bind(&third);
    app_panes_apply_state(&third, &cfg);
    CHECK(third.right.tab_count == 0);

    net_bind(app);
}

// Esc closes the dialog, and while its filter field holds the keyboard the
// arrows edit the word instead of walking the file list behind it.
static void test_options_keys(AppPanes* app) {
    Pane& p = app->left;
    refresh_pane(&p, "/tmp");
    int sel = p.selected;

    CHECK(app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));    // normally the pane's key

    app->options_open = true;
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(!app->options_open);                                   // Esc closes it

    app->options_open = true;
    app->options_field_active = true;
    CHECK(!app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));   // now the field's
    CHECK(!app_key_is_special(SDLK_DELETE, SDL_KMOD_NONE, app));
    CHECK(!app_key_is_special(SDLK_HOME, SDL_KMOD_NONE, app));
    // Not special means the harness hands the key to ImGui instead of to the
    // pane handler, which is what keeps the cursor where it is.
    app->options_field_active = false;
    CHECK(app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));    // and back to normal
    app->options_open = false;
}

// The remote dialogs are windows over the panes, not widgets beside them, so a
// key the dialog does not take must still not reach the file list. What this
// pins is the reported bug: Enter with the site manager open activated whatever
// the pane cursor happened to be sitting on.
static void test_remote_keys(AppPanes* app) {
    Pane& p = app->left;
    refresh_pane(&p, "/tmp");
    CHECK(p.entry_count > 1);
    p.selected = 1;
    int sel = p.selected;

    app->remote_mgr_open = true;
    app->remote_edit = -1;
    // No field is up, so these stay app keys - but the pane must not act on them.
    CHECK(app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(p.selected == sel);                                  // Enter did not open a row
    app_panes_handle_key(app, SDLK_DOWN, SDL_KMOD_NONE);
    CHECK(p.selected == sel);                                  // nor did the arrow walk it
    app_panes_handle_key(app, SDLK_SPACE, SDL_KMOD_NONE);
    CHECK(!p.marked[sel]);                                     // nor did Space mark it

    // The list of connections is walked with the arrows and opened with Enter. It
    // is the saved sites followed by this session's quick connects, so a site
    // connected to with Ctrl+N a moment ago is one keypress from a keyboard even
    // though it was never written to the sites file.
    app->remote_sites.clear();
    app->remote_adhoc.clear();
    NetSite one; one.name = "one";     one.host = "one.example";   one.proto = NET_FTP;
    NetSite two; two.name = "two";     two.host = "two.example";   two.proto = NET_FTP;
    NetSite three; three.name = "three"; three.host = "three.example"; three.proto = NET_FTP;
    app->remote_sites.push_back(one);
    app->remote_sites.push_back(two);
    app->remote_adhoc.push_back(three);
    CHECK(net_rows(app).size() == 3);
    CHECK(!net_rows(app)[1].adhoc && net_rows(app)[1].idx == 1);
    CHECK(net_rows(app)[2].adhoc && net_rows(app)[2].idx == 0);

    CHECK(net_cursor_step(-1, 3, SDLK_DOWN) == 0);   // no cursor: Down enters at the top
    CHECK(net_cursor_step(-1, 3, SDLK_UP) == 2);     // and Up at the bottom
    CHECK(net_cursor_step(2, 3, SDLK_DOWN) == 2);    // it stops at the ends
    CHECK(net_cursor_step(0, 3, SDLK_UP) == 0);
    CHECK(net_cursor_step(1, 3, SDLK_HOME) == 0);
    CHECK(net_cursor_step(1, 3, SDLK_END) == 2);
    CHECK(net_cursor_step(0, 30, SDLK_PAGEDOWN) == 10);
    CHECK(net_cursor_step(29, 30, SDLK_PAGEUP) == 19);
    CHECK(net_cursor_step(1, 3, SDLK_SPACE) == 1);   // not a navigation key
    CHECK(net_cursor_step(2, 0, SDLK_DOWN) == -1);   // an empty list has no cursor

    app->remote_cursor = -1;
    app_panes_handle_key(app, SDLK_DOWN, SDL_KMOD_NONE);
    CHECK(app->remote_cursor == 0);
    app_panes_handle_key(app, SDLK_DOWN, SDL_KMOD_NONE);
    app_panes_handle_key(app, SDLK_DOWN, SDL_KMOD_NONE);
    app_panes_handle_key(app, SDLK_DOWN, SDL_KMOD_NONE);
    CHECK(app->remote_cursor == 2);                  // clamped at the end, not wrapped
    app_panes_handle_key(app, SDLK_UP, SDL_KMOD_NONE);
    CHECK(app->remote_cursor == 1);
    CHECK(app->left.selected == sel);                // the pane behind is still untouched
    // With the editor up the arrows are caret keys, so the cursor holds still.
    g_net_form.open = true;
    CHECK(!app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));
    app_panes_handle_key(app, SDLK_DOWN, SDL_KMOD_NONE);
    CHECK(app->remote_cursor == 1);
    g_net_form.open = false;
    app_panes_handle_key(app, SDLK_END, SDL_KMOD_NONE);
    CHECK(app->remote_cursor == 2);
    // Ctrl+F is the documented way out of the manager, so it is the one key the
    // catch-all deliberately leaves through.
    app_panes_handle_key(app, SDLK_F, SDL_KMOD_CTRL);
    CHECK(!app->remote_mgr_open);

    // Quick connect always has a field up, so the caret keys belong to it. These
    // are all app keys normally, which is exactly what breaks typing a URL.
    CHECK(app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));    // the baseline, dialog still shut
    app->remote_quick_open = true;
    CHECK(!app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));
    CHECK(!app_key_is_special(SDLK_HOME, SDL_KMOD_NONE, app));
    CHECK(!app_key_is_special(SDLK_BACKSPACE, SDL_KMOD_NONE, app));
    CHECK(!app_key_is_special(SDLK_DELETE, SDL_KMOD_NONE, app));
    // A URL that will not parse is refused without moving the pane, and the
    // dialog stays up with the reason on screen so there is something to fix.
    app->remote_quick[0] = '\0';
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(p.selected == sel);
    CHECK(app->remote_quick_open);
    CHECK(app->remote_note[0]);
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(!app->remote_quick_open);
    CHECK(app_key_is_special(SDLK_DOWN, SDL_KMOD_NONE, app));    // and back to normal

    app->remote_mgr_open = false;
    app->remote_edit = -1;
    app->remote_cursor = -1;
    app->remote_note[0] = '\0';
    app->remote_sites.clear();
    app->remote_adhoc.clear();
}

// The operation dialog is the one place in this app with buttons, and ImGui's
// keyboard navigation is switched off here because the panes own the arrow keys. So
// the ring that reaches those buttons is the app's own, and the only way to know it
// works is to drive the keys: which control Tab lands on, what Enter does there, and
// what Tab has to stop doing while a destination is being typed.
static void test_op_tab_ring(AppPanes* app) {
    const bool focus_was = app->left_focus;

    // A local copy offers three controls: the field, Copy, Cancel.
    app->op = OP_COPY;
    app->op_plan = OpPlan();
    app->op_plan.dst_dir = "/tmp";
    snprintf(app->op_name, sizeof(app->op_name), "/tmp/");
    app->op_focus = OF_FIELD;

    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_RUN);
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_CANCEL);      // a local plan has no background button
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_FIELD);       // the ring wraps back through the field
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_SHIFT);
    CHECK(app->op_focus == OF_CANCEL);      // Shift+Tab walks back the same way
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_SHIFT);
    CHECK(app->op_focus == OF_RUN);

    // Tab is the pane switch when no dialog is up. It has to stop being one the
    // moment the dialog owns the keyboard, or reaching for "Cancel" moves a pane
    // behind the dialog and changes what the operation applies to.
    CHECK(app->left_focus == focus_was);

    // A copy to a site gains a button, so the ring is four long. The ids keep their
    // meaning as it grows: Cancel is still Cancel, not whatever shifted into its place.
    snprintf(app->op_name, sizeof(app->op_name), "ftp://nowhere.example/pub/");
    CHECK(op_dialog_network(app));
    app->op_focus = OF_FIELD;
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_RUN);
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_BG);
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_CANCEL);
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_FIELD);

    // Enter runs what the ring sits on. On Cancel that means closing the dialog with
    // nothing recorded, so no operation is left waiting to run between frames.
    app->op_focus = OF_CANCEL;
    app->pending_op = DEFER_NONE;
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op == OP_NONE);
    CHECK(app->pending_op == DEFER_NONE);

    // On "Run in background" it is the same commit the button makes, with the
    // request raised and no Shift held. The site is unknown, so the commit keeps the
    // dialog up instead of reaching the network; the request is what is being read.
    app->op = OP_COPY;
    app->op_plan = OpPlan();
    app->op_plan.dst_dir = "/tmp";
    snprintf(app->op_name, sizeof(app->op_name), "ftp://nowhere.example/pub/");
    app->op_focus = OF_BG;
    app->op_run_bg = false;
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_NONE);
    CHECK(app->op_run_bg);
    CHECK(app->op == OP_COPY);
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);

    // A focus the dialog can no longer draw is not left pointing at a button that is
    // not there: the destination was edited from a site to a local directory and the
    // ring lost a member, so Tab starts from the field rather than from a gap.
    app->op = OP_COPY;
    app->op_plan = OpPlan();
    app->op_plan.dst_dir = "/tmp";
    snprintf(app->op_name, sizeof(app->op_name), "ftp://nowhere.example/pub/");
    app->op_focus = OF_BG;
    snprintf(app->op_name, sizeof(app->op_name), "/tmp/");
    CHECK(!op_dialog_network(app));
    app_panes_handle_key(app, SDLK_TAB, SDL_KMOD_NONE);
    CHECK(app->op_focus == OF_RUN);

    // Both ways of opening a dialog start the ring on the field, whatever the last
    // one was left on: the first thing a user does with a dialog is type in it.
    app->op = OP_NONE;
    app->op_focus = OF_CANCEL;
    open_name_dialog(app, OP_MKDIR, "");
    CHECK(app->op == OP_MKDIR && app->op_focus == OF_FIELD);
    app_panes_cancel_op(app);

    app->op_focus = OF_CANCEL;
    OpPlan p;
    p.src_dir = "/tmp";
    p.dst_dir = "/tmp";
    p.names.push_back("a");
    open_op_dialog(app, p);
    CHECK(app->op == OP_COPY && app->op_focus == OF_FIELD);
    app_panes_cancel_op(app);

    app->op = OP_NONE;
    app->op_plan = OpPlan();
    app->op_name[0] = '\0';
    app->op_focus = OF_FIELD;
    app->op_run_bg = false;
    app->pending_op = DEFER_NONE;
    app->left_focus = focus_was;
}

// A copy or move across a network can be handed to a thread, and the strip under
// the panes is the only thing that says what that thread is doing. The numbers are
// the part worth checking: they are read off atomics by a frame that can catch the
// transfer at any moment, and they have to stay readable when the size is not
// known yet or the transfer has already ended.
static void test_bg_transfers(AppPanes* app) {
    char out[256];

    fmt_secs(0.4, out, sizeof(out));   CHECK(!strcmp(out, "0s"));
    fmt_secs(59.4, out, sizeof(out));  CHECK(!strcmp(out, "59s"));
    fmt_secs(125, out, sizeof(out));   CHECK(!strcmp(out, "2m05s"));
    fmt_secs(3720, out, sizeof(out));  CHECK(!strcmp(out, "1h02m"));
    fmt_secs(-5, out, sizeof(out));    CHECK(!strcmp(out, "0s"));   // never a negative ETA

    BgTransfer t;
    t.state  = BgTransfer::BG_RUNNING;
    t.abort = t.settled = t.dismiss = false;
    t.done = t.total = 0;
    t.files_done = t.files_total = 0;
    t.is_move = false;
    t.download = true;
    // Ten seconds of history makes the rate exact enough to assert on.
    t.t0 = SDL_GetTicks() / 1000.0 - 10.0;
    t.done = 5000000;
    t.total = 10000000;
    bg_line(&t, out, sizeof(out));
    CHECK(strstr(out, "5.0M of 10.0M") != nullptr);
    CHECK(strstr(out, "5.0M left") != nullptr);
    CHECK(strstr(out, "eta 10s") != nullptr);

    // A tree whose sizes the server has not named yet: a bar that never moves
    // needs a line that says why.
    t.total = 0;
    bg_line(&t, out, sizeof(out));
    CHECK(strstr(out, "size not known yet") != nullptr);
    CHECK(strstr(out, "eta") == nullptr);

    // An ended transfer has no rate to quote, only what it moved and how long
    // that took - and how long that took is the transfer's span, not how long ago
    // it started. The row is still drawn a minute later, so a duration measured
    // against the clock counts up under a bar that says "done". The timestamps are
    // fixed rather than read from the clock, because the claim is that this line
    // does not read the clock.
    t.state = BgTransfer::BG_DONE;
    t.t0 = 1000.0;
    t.t_end_ms = 1000000;                       // ended the instant it began
    bg_line(&t, out, sizeof(out));
    CHECK(strstr(out, "5.0M in 0s") != nullptr);
    t.t_end_ms = 1009000;                       // ran nine of its ten seconds
    bg_line(&t, out, sizeof(out));
    CHECK(strstr(out, "5.0M in 9s") != nullptr);
    char frozen[128];
    snprintf(frozen, sizeof(frozen), "%s", out);
    SDL_Delay(150);                                     // the row is still on screen
    bg_line(&t, out, sizeof(out));
    CHECK(!strcmp(out, frozen));                        // and the number has not moved
    t.t_end_ms = 0;                                     // a finish never recorded
    bg_line(&t, out, sizeof(out));
    CHECK(strstr(out, "in 0s") != nullptr);

    // The worker's callback publishes instead of drawing, and its false answer is
    // what unwinds the transport after the file it is on.
    t.state = BgTransfer::BG_RUNNING;
    CHECK(bg_progress_cb(1024, 4096, 2, 5, &t));
    CHECK(t.done == 1024 && t.total == 4096);
    CHECK(t.files_done == 2 && t.files_total == 5);
    t.abort = true;
    CHECK(!bg_progress_cb(2048, 4096, 3, 5, &t));
    t.abort = false;

    // Only a transfer that crosses a network can be handed over. A local copy is
    // bounded by the disk, and a second thread into the same tree buys a race. The
    // destination can still be sitting in the dialog's field rather than in the
    // plan, so the field is asked as well.
    OpPlan plan;
    plan.dst_dir = "/tmp";
    CHECK(!plan_crosses_network(plan, "/tmp/out"));
    CHECK(plan_crosses_network(plan, "ftp://example.com/pub/"));   // typed into the field
    plan.remote = "ftp://example.com";
    CHECK(plan_crosses_network(plan, "/tmp/out"));
    plan.remote.clear();
    plan.dst_dir = "ftp://example.com/pub";
    CHECK(plan_crosses_network(plan, "/tmp/out"));

    // Shift+Enter is the keyboard half of the dialog's button. The destination is
    // not resolved until the commit runs, so the key raises the request for any
    // copy or move and the run is what decides whether it meant anything - which
    // is also what stops it leaking into the next operation.
    app->op = OP_COPY;
    app->op_plan = OpPlan();
    app->op_plan.dst_dir = "/tmp";
    snprintf(app->op_name, sizeof(app->op_name), "ftp://nowhere.example/pub/");
    app->op_run_bg = false;
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_SHIFT);
    CHECK(app->op_run_bg);                       // the request is raised...
    CHECK(app->op == OP_COPY);                   // ...and the dialog is still up, refusing the site
    app_panes_handle_key(app, SDLK_ESCAPE, SDL_KMOD_NONE);
    CHECK(!app->op_run_bg);                      // cancelling drops it with the plan

    app->op = OP_COPY;
    app->op_plan = OpPlan();
    app->op_plan.dst_dir = "/tmp";
    snprintf(app->op_name, sizeof(app->op_name), "/tmp/");
    app->op_run_bg = false;
    app_panes_handle_key(app, SDLK_RETURN, SDL_KMOD_SHIFT);
    CHECK(app->op_run_bg);
    app_panes_run_pending(app);                  // a local plan runs, and drops the request
    CHECK(!app->op_run_bg);
    app->op = OP_NONE;
    app->op_plan = OpPlan();

    // The strip takes no room at all while there is nothing in it.
    CHECK(bg_strip_height(app, 20.0f) == 0.0f);

    // A finished transfer is settled once: one status line, one refresh of the
    // panes that can see the destination. It stays on screen until dismissed.
    app->transfers.clear();
    std::unique_ptr<BgTransfer> up = std::make_unique<BgTransfer>();
    BgTransfer* row = up.get();
    row->state = BgTransfer::BG_DONE;
    row->abort = row->settled = row->dismiss = false;
    row->done = row->total = 0;
    row->files_done = row->files_total = 0;
    row->is_move = false;
    row->download = true;
    row->t0 = SDL_GetTicks() / 1000.0;
    row->dst = "/tmp/bg-dest";
    row->ok_names = 3;
    row->worker = std::thread([] {});
    app->transfers.push_back(std::move(up));
    CHECK(bg_strip_height(app, 20.0f) > 0.0f);

    app->status_msg[0] = '\0';
    bg_reap(app);
    CHECK(strstr(app->status_msg, "Copied 3 items to /tmp/bg-dest") != nullptr);
    CHECK(row->settled.load());
    snprintf(app->status_msg, sizeof(app->status_msg), "untouched");
    bg_reap(app);
    CHECK(!strcmp(app->status_msg, "untouched"));   // a second frame says it once
    CHECK(app->transfers.size() == 1);              // it stays until dismissed
    row->dismiss = true;
    bg_reap(app);
    CHECK(app->transfers.empty());                  // joined, then dropped

    // Quit asks every running transfer to stop and waits for it to come back, so
    // nothing is still inside libcurl when the library is released.
    up = std::make_unique<BgTransfer>();
    row = up.get();
    row->state = BgTransfer::BG_RUNNING;
    row->abort = row->settled = row->dismiss = false;
    row->done = row->total = 0;
    row->files_done = row->files_total = 0;
    row->is_move = false;
    row->download = true;
    row->t0 = SDL_GetTicks() / 1000.0;
    row->worker = std::thread([row] {
        while (!row->abort.load()) SDL_Delay(1);
        row->state.store(BgTransfer::BG_ABORTED, std::memory_order_release);
    });
    app->transfers.push_back(std::move(up));
    bg_stop_all(app);
    CHECK(app->transfers.empty());                  // joined, not abandoned

    // A background transfer needs a login before a thread is worth starting, and
    // the refusal says so the way the foreground path does.
    app->transfers.clear();
    OpPlan want;
    want.remote = "ftp://nowhere.example";
    want.remote_prefix = "/pub";
    want.dst_dir = "/tmp/bg-dest";
    want.names.push_back("gone.txt");
    app->status_msg[0] = '\0';
    bg_start_remote_plan(app, want);
    CHECK(app->transfers.empty());
    CHECK(strstr(app->status_msg, "No login for ftp://nowhere.example") != nullptr);

    // Finished rows are retired to make room for a new transfer, but a running one
    // is never taken out from under the thread that is reporting into it.
    std::unique_ptr<BgTransfer> running = std::make_unique<BgTransfer>();
    BgTransfer* live = running.get();
    live->state = BgTransfer::BG_RUNNING;
    live->abort = live->settled = live->dismiss = false;
    live->done = live->total = 0;
    live->files_done = live->files_total = 0;
    live->is_move = false;
    live->download = true;
    live->t0 = SDL_GetTicks() / 1000.0;
    live->worker = std::thread([live] {
        while (!live->abort.load()) SDL_Delay(1);
        live->state.store(BgTransfer::BG_ABORTED, std::memory_order_release);
    });
    up = std::make_unique<BgTransfer>();
    row = up.get();
    row->state = BgTransfer::BG_DONE;
    row->abort = row->settled = row->dismiss = false;
    row->done = row->total = 0;
    row->files_done = row->files_total = 0;
    row->is_move = false;
    row->download = true;
    row->t0 = SDL_GetTicks() / 1000.0;
    row->worker = std::thread([] {});
    app->transfers.push_back(std::move(running));
    app->transfers.push_back(std::move(up));
    bg_retire_oldest_finished(app);
    CHECK(app->transfers.size() == 1);
    CHECK(app->transfers[0].get() == live);   // the finished one went, the running one stayed
    bg_stop_all(app);
    CHECK(app->transfers.empty());

    // The bar says "running" by moving; the number it cannot show by itself is how
    // far along the transfer is, so that is what goes on the bar. A finished row
    // keeps its word, and a running row with no total yet has no percentage to show.
    char ov[32];
    bg_overlay(BgTransfer::BG_RUNNING, 5, 10, ov, sizeof(ov));
    CHECK(!strcmp(ov, "50%"));
    bg_overlay(BgTransfer::BG_RUNNING, 1, 3, ov, sizeof(ov));
    CHECK(!strcmp(ov, "33%"));
    bg_overlay(BgTransfer::BG_RUNNING, 12, 10, ov, sizeof(ov));
    CHECK(!strcmp(ov, "100%"));                 // a total that grew mid-transfer
    bg_overlay(BgTransfer::BG_RUNNING, 0, 0, ov, sizeof(ov));
    CHECK(!strcmp(ov, "running"));              // nothing known about the size yet
    bg_overlay(BgTransfer::BG_DONE, 10, 10, ov, sizeof(ov));
    CHECK(!strcmp(ov, "done"));
    bg_overlay(BgTransfer::BG_FAILED, 3, 10, ov, sizeof(ov));
    CHECK(!strcmp(ov, "failed"));

    // A copy that crosses a network is on its own thread whether or not the user
    // asked for the background, so the progress dialog can stop watching at any
    // moment - the handover changes who is watching, not what is running.
    std::unique_ptr<BgTransfer> hand = std::make_unique<BgTransfer>();
    BgTransfer* ht = hand.get();
    ht->state = BgTransfer::BG_RUNNING;
    ht->abort = ht->settled = ht->dismiss = false;
    ht->src = "ftp://site/big.bin";
    ht->dst = "/tmp/bg-dst/big.bin";
    ht->done = 5; ht->total = 10;
    ht->files_done = 0; ht->files_total = 1;
    ht->is_move = false;
    ht->download = true;
    ht->t0 = SDL_GetTicks() / 1000.0;
    snprintf(app->status_msg, sizeof(app->status_msg), "untouched");
    ht->worker = std::thread([ht] {
        while (!ht->abort.load()) SDL_Delay(2);
        ht->ok_names = 1;
        ht->state.store(BgTransfer::BG_ABORTED, std::memory_order_release);
    });
    app->transfers.push_back(std::move(hand));

    prog_begin_watch(app, ht);
    CHECK(app->prog_watch == ht);
    CHECK(app->prog_active);
    CHECK(!app->prog_handoff);
    CHECK(!strcmp(app->prog_src, "ftp://site/big.bin"));   // the dialog speaks of the same thing
    CHECK(watch_transfer_tick(app, ht));                    // still going, so keep watching
    app->prog_handoff = true;                              // what the dialog's button sets
    CHECK(!watch_transfer_tick(app, ht));                   // and the watching stops
    app->prog_active = false;
    app->prog_watch = nullptr;
    CHECK(!ht->abort.load());                               // the transfer was not asked to stop
    CHECK(ht->state.load() == BgTransfer::BG_RUNNING);
    CHECK(app->transfers.size() == 1);                     // the row under the panes has it already

    // Watching one that finishes on its own ends by itself, and the settle - the
    // status line, the refresh of the destination pane - is still the list's job.
    std::unique_ptr<BgTransfer> fin = std::make_unique<BgTransfer>();
    BgTransfer* over = fin.get();
    over->state = BgTransfer::BG_RUNNING;
    over->abort = over->settled = over->dismiss = false;
    over->src = "ftp://site/one.txt";
    over->dst = "/tmp/bg-dst/one.txt";
    over->done = over->total = 10;
    over->files_done = 1; over->files_total = 1;
    over->is_move = false;
    over->download = true;
    over->t0 = SDL_GetTicks() / 1000.0;
    over->worker = std::thread([over] {
        SDL_Delay(40);
        over->ok_names = 1;
        over->state.store(BgTransfer::BG_DONE, std::memory_order_release);
    });
    app->transfers.push_back(std::move(fin));
    watch_remote_transfer(app, over);
    CHECK(!app->prog_active);
    CHECK(app->prog_watch == nullptr);
    CHECK(!app->prog_handoff);
    CHECK(over->state.load() == BgTransfer::BG_DONE);
    bg_reap(app);
    CHECK(strstr(app->status_msg, "Copied 1 item to") != nullptr);

    // The button is in the dialog only when there is a thread to hand over to. A
    // copy running on this thread is the dialog, so there is nothing to hand over.
    {
        ImGuiContext* ctx = ImGui::CreateContext();
        ImGuiIO& io = ImGui::GetIO();
        io.IniFilename = nullptr;
        io.DisplaySize = ImVec2(900, 700);
        unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
        io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);

        // Hover is decided while the item is being submitted, so every probe
        // frame has to draw the dialog again with the mouse already moved. The
        // button's id is the window's seed hashed with its label, which is what
        // GetID() would return at the window's root - and it cannot be asked
        // outside a frame, where the window's id stack is empty.
        auto dialog = [app]() { ImGui::NewFrame(); render_progress_dialog(app); ImGui::Render(); };
        auto hover = [&](ImGuiWindow* w, ImGuiID want) -> ImVec2 {
            for (int y = (int)w->Pos.y; y < (int)(w->Pos.y + w->Size.y); y += 4)
                for (int x = (int)w->Pos.x; x < (int)(w->Pos.x + w->Size.x); x += 4) {
                    io.AddMousePosEvent((float)x, (float)y);
                    dialog();
                    if (ImGui::GetHoveredID() == want) return ImVec2((float)x, (float)y);
                }
            return ImVec2(-1.0f, -1.0f);
        };
        auto button_id = [](ImGuiWindow* w, const char* label) {
            return ImHashStr(label, 0, w->ID);
        };

        app->prog_active = true;
        app->prog_is_move = false;
        app->prog_is_delete = false;
        app->prog_abort = false;
        app->prog_handoff = false;
        app->prog_done = 5; app->prog_total = 10;
        snprintf(app->prog_src, sizeof(app->prog_src), "/local/src");
        snprintf(app->prog_dst, sizeof(app->prog_dst), "/local/dst");
        app->prog_watch = nullptr;
        dialog();
        ImGuiWindow* w = ImGui::FindWindowByName("Copying");
        CHECK(w != nullptr);
        if (w) {
            CHECK(hover(w, button_id(w, "Run in background")).x < 0.0f);   // nothing to hand over
            CHECK(hover(w, button_id(w, "Abort")).x >= 0.0f);              // but Abort always is
        }

        app->prog_watch = over;      // a transfer that is on a thread
        app->prog_handoff = false;
        dialog();
        w = ImGui::FindWindowByName("Copying");
        if (w) {
            ImVec2 at = hover(w, button_id(w, "Run in background"));
            CHECK(at.x >= 0.0f);
            if (at.x >= 0.0f) {
                io.AddMousePosEvent(at.x, at.y);
                io.AddMouseButtonEvent(0, true);
                dialog();
                io.AddMouseButtonEvent(0, false);
                dialog();
            }
            CHECK(app->prog_handoff);
            CHECK(!over->abort.load());   // handing over is not asking it to stop
        }
        app->prog_watch = nullptr;
        app->prog_active = false;
        ImGui::DestroyContext(ctx);
    }

    bg_stop_all(app);
    CHECK(app->transfers.empty());
}

// A pane that walks onto a site it has no login for gets no listing. The rows it
// freed on the way in are gone, so the count that used to reach them has to go
// with them: a count over freed rows is a crash waiting for the next frame that
// draws the pane, and the way to reach it is a saved tab for a site the user has
// since deleted from the site list.
static void test_failed_list_has_no_rows(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    const std::string d = root + "/no-listing";
    sh("rm -rf '" + d + "' && mkdir -p '" + d + "' && touch '" + d + "/one.txt'");
    refresh_pane(&p, d.c_str());
    CHECK(p.entry_count > 0);
    refresh_pane(&p, "ftp://nobody@nowhere.invalid/pub");
    CHECK(in_remote(p));
    CHECK(p.entries == nullptr);
    CHECK(p.entry_count == 0);
    // The pane is still a pane: walking back to a real directory lists it again.
    refresh_pane(&p, d.c_str());
    CHECK(p.entry_count > 0);
    sh("rm -rf '" + d + "'");
}

// The fetch a quick view has running for a path, if it has one.
static QvFetch* qv_fetch_for(AppPanes* app, const std::string& key) {
    for (std::unique_ptr<QvFetch>& f : app->qv_fetches)
        if (f->key == key) return f.get();
    return nullptr;
}

// Quick view over a file the pane is looking at but cannot fopen(): a member of
// an archive, and a file on a site. The archive half runs the real worker thread
// and the real unpacking, so the whole path is covered - ask, fetch off the UI
// thread, reap the answer into the cache, and answer the next frame from the
// cache without asking the disk or the server again.
static void test_quick_view(AppPanes* app, const std::string& root) {
    Pane& p = app->left;
    const std::string qv = root + "/qv";
    sh("rm -rf '" + qv + "' && mkdir -p '" + qv + "/src'");
    sh("printf 'alpha\\r\\nbeta\\n' > '" + qv + "/src/plain.txt'");
    sh("printf 'inner line\\n' > '" + qv + "/src/inner.txt'");
    {
        FILE* f = fopen((qv + "/src/bin.dat").c_str(), "wb");
        if (f) { fwrite("a\0b", 1, 3, f); fclose(f); }
    }
    {
        StringList names;
        names.push_back("plain.txt");
        names.push_back("inner.txt");
        names.push_back("bin.dat");
        std::string err;
        CHECK(arch_pack((qv + "/pkg.zip").c_str(), (qv + "/src").c_str(), names,
                        nullptr, nullptr, &err));
    }

    // A CRLF becomes one newline and a lone CR becomes one: ImGui advances over a
    // carriage return instead of breaking the line, so a text file written on
    // Windows would otherwise preview as one very long row.
    std::string crlf = "two\r\nlines\n";
    CHECK(qv_to_text(&crlf));
    CHECK(crlf == "two\nlines\n");
    std::string lone = "a\rb";
    CHECK(qv_to_text(&lone));
    CHECK(lone == "a\nb");
    std::string nul("a\0b", 3);
    CHECK(!qv_to_text(&nul));

    // A local file is read in the frame and filed under its path, so the row keeps
    // answering after the file goes: arrowing through a directory asks once per
    // name, not once per keypress.
    refresh_pane(&p, (qv + "/src").c_str());
    int plain = idx_of(p, "plain.txt");
    CHECK(plain >= 0);
    CHECK(qv_preview(app, p, plain) == "alpha\nbeta\n");
    sh("rm -f '" + qv + "/src/plain.txt'");
    CHECK(qv_preview(app, p, plain) == "alpha\nbeta\n");
    CHECK(qv_preview(app, p, idx_of(p, "bin.dat")) == k_qv_binary);
    CHECK(qv_preview(app, p, 0).empty());      // ".." is a directory: nothing to show

    // A row whose file is gone says so, and the answer is not kept, so the name is
    // read again once the file comes back.
    sh("touch '" + qv + "/src/ghost.txt'");
    refresh_pane(&p, (qv + "/src").c_str());
    int ghost = idx_of(p, "ghost.txt");
    CHECK(ghost >= 0);
    sh("rm -f '" + qv + "/src/ghost.txt'");
    const std::string ghost_path = qv + "/src/ghost.txt";
    CHECK(qv_preview(app, p, ghost) == "(cannot read " + ghost_path + ")");
    CHECK(qv_cache_find(app, ghost_path) == nullptr);

    // What reading a row would take, for a row of each kind.
    QvJob job;
    CHECK(qv_job_for(app, p, idx_of(p, "inner.txt"), &job));
    CHECK(job.kind == QV_LOCAL);
    CHECK(job.key == qv + "/src/inner.txt");
    CHECK(job.path == job.key);
    CHECK(pane_row_path(p, idx_of(p, "inner.txt")) == qv + "/src/inner.txt");

    // Inside an archive: the member is unpacked on a thread, and the frame that
    // asked gets a placeholder while it is on its way.
    refresh_pane(&p, (qv + "/pkg.zip").c_str());
    CHECK(in_archive(p));
    int member = idx_of(p, "inner.txt");
    CHECK(member >= 0);
    CHECK(qv_job_for(app, p, member, &job));
    CHECK(job.kind == QV_ARCHIVE);
    CHECK(job.path == qv + "/pkg.zip");
    CHECK(job.member == "inner.txt");
    const std::string member_key = qv + "/pkg.zip/inner.txt";
    CHECK(job.key == member_key);
    CHECK(qv_preview(app, p, member) == k_qv_reading);
    CHECK(app->qv_fetches.size() == 1);
    CHECK(app->qv_fetches[0]->key == member_key);
    // Asking again while it is running must not start a second fetch for it.
    CHECK(qv_preview(app, p, member) == k_qv_reading);
    CHECK(app->qv_fetches.size() == 1);
    // The answer lands on a later frame. The wait is bounded so a fetch that never
    // answers fails the test instead of hanging it.
    std::string text = k_qv_reading;
    for (int tries = 0; tries < 200 && text == k_qv_reading; tries++) {
        SDL_Delay(25);
        qv_reap(app);
        text = qv_preview(app, p, member);
    }
    CHECK(text == "inner line\n");
    CHECK(app->qv_fetches.empty());
    CHECK(qv_cache_find(app, member_key) != nullptr);

    // Two quick views open at once - F3 over each pane, or F3 and the Ctrl+Q
    // panel - ask for two different rows in the same frame. Neither is stale, so
    // neither may be told to stop. The rule this pins down used to cancel every
    // other fetch in order to start one view's fetch, which cancelled the other
    // view's: that one restarted next frame and cancelled the first back, so a
    // preview over a site aborted before its bytes arrived and the server took a
    // connect and an abort per frame.
    int m_plain = idx_of(p, "plain.txt");
    int m_bin   = idx_of(p, "bin.dat");
    CHECK(m_plain >= 0 && m_bin >= 0);
    CHECK(qv_preview(app, p, m_plain) == k_qv_reading);   // one view's cursor
    CHECK(qv_preview(app, p, m_bin)   == k_qv_reading);   // the other view's
    CHECK(app->qv_fetches.size() == 2);
    const std::string plain_key = qv + "/pkg.zip/plain.txt";
    const std::string bin_key   = qv + "/pkg.zip/bin.dat";
    CHECK(qv_fetch_for(app, plain_key) != nullptr);
    CHECK(qv_fetch_for(app, bin_key) != nullptr);
    for (std::unique_ptr<QvFetch>& f : app->qv_fetches) CHECK(!f->cancel.load());
    qv_stop_all(app);

    // Which fetches a frame leaves running, decided without a worker so nothing
    // here depends on how fast a thread happens to be. A record that has not
    // answered is skipped by the reaping half of qv_reap() and never joined, so
    // these observe the cancelling half on its own.
    auto fake = [&](const char* key, bool wanted) {
        std::unique_ptr<QvFetch> up = std::make_unique<QvFetch>();
        up->key = key;
        up->wanted = wanted;
        QvFetch* raw = up.get();
        app->qv_fetches.push_back(std::move(up));
        return raw;
    };
    QvFetch* asked   = fake("asked", true);      // the frame that just drew asked
    QvFetch* ignored = fake("ignored", false);   // and nobody asked for this one
    qv_reap(app);
    CHECK(!asked->cancel.load());
    CHECK(ignored->cancel.load());
    // The claim does not carry over: a fetch that stops being asked for is stopped
    // by the frame after the one that stopped asking.
    qv_reap(app);
    CHECK(asked->cancel.load());
    qv_stop_all(app);

    // A quick view that finds a fetch already on its way claims it, so the next
    // frame's reap leaves it alone instead of stopping it, and does not start a
    // second one for the same name.
    QvFetch* onitsway = fake(plain_key.c_str(), false);
    CHECK(qv_preview(app, p, m_plain) == k_qv_reading);
    CHECK(app->qv_fetches.size() == 1);
    qv_reap(app);
    CHECK(!onitsway->cancel.load());
    // The cap is one fetch per quick view the app can show at once, so a fourth
    // name waits rather than piling up threads.
    fake("a", true); fake("b", true); fake("c", true);
    CHECK(qv_preview(app, p, m_bin) == k_qv_reading);
    CHECK(app->qv_fetches.size() == 4);   // the three fakes plus the one on its way
    qv_stop_all(app);

    // On a site: the row's path on the server, and a copy of the site, because a
    // saved site can be edited while the thread that was given it is still running.
    NetSite site;
    site.name = "qv";
    site.proto = NET_FTP;
    site.host = "127.0.0.1";
    site.port = 1;              // nothing listens here: the connect is refused at once
    site.user = "someone";
    site.password = "secret";
    app->remote_sites.push_back(site);
    net_bind(app);
    const std::string site_url = net_site_root(site);
    refresh_pane(&p, (site_url + "/pub").c_str());
    CHECK(in_remote(p));
    free_entries(p.entries, p.entry_count);
    p.entries = (FileEntry**)malloc(sizeof(FileEntry*) * 2);
    p.entries[0] = file_entry_new("..", S_IFDIR | 0755, 0, 0);
    p.entries[1] = file_entry_new("far.txt", S_IFREG | 0644, 10, 0);
    p.entry_count = 2;
    int far = idx_of(p, "far.txt");
    CHECK(far >= 0);
    CHECK(qv_job_for(app, p, far, &job));
    CHECK(job.kind == QV_REMOTE);
    CHECK(job.rpath == "/pub/far.txt");
    CHECK(job.site.host == site.host && job.site.password == site.password);
    CHECK(pane_row_path(p, far) == site_url + "/pub/far.txt");
    // A fetch that cannot be answered still answers: it fails, and a failure is
    // not kept, so the name is asked again after the site comes back.
    const std::string far_key = site_url + "/pub/far.txt";
    CHECK(qv_preview(app, p, far) == k_qv_reading);
    for (int tries = 0; tries < 200 && !app->qv_fetches.empty(); tries++) {
        SDL_Delay(25);
        qv_reap(app);
    }
    CHECK(app->qv_fetches.empty());
    CHECK(qv_cache_find(app, far_key) == nullptr);

    // The cache holds a bounded number of previews, oldest first.
    for (size_t n = 0; n < k_qv_cache_max + 7; n++)
        qv_cache_put(app, "k" + std::to_string(n), "v");
    CHECK(app->qv_cache.size() == k_qv_cache_max);
    CHECK(qv_cache_find(app, "k0") == nullptr);
    CHECK(qv_cache_find(app, "k" + std::to_string(k_qv_cache_max + 6)) != nullptr);
    qv_cache_put(app, "k7", "w");
    CHECK(*qv_cache_find(app, "k7") == "w");
    CHECK(app->qv_cache.size() == k_qv_cache_max);

    // Quitting with a fetch still running: it is asked to stop and joined before
    // the transport goes away underneath it.
    CHECK(qv_preview(app, p, far) == k_qv_reading);
    qv_stop_all(app);
    CHECK(app->qv_fetches.empty());

    app->qv_cache.clear();
    app->remote_sites.clear();
    free_entries(p.entries, p.entry_count);
    p.entries = nullptr;
    p.entry_count = 0;
    p.selected = 0;
    p.current_dir[0] = '\0';
    p.remote_root[0] = '\0';
    p.remote_path[0] = '\0';
    p.list_mode = LIST_NORMAL;
}

// The dialog has to fit the window it is opened in, and a font path has to stay
// inside it: the list is a column of long absolute paths, which is exactly what
// pushes a frame wider than the screen.
static void test_options_dialog_layout(AppPanes* app) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(420, 300);           // a window a person can resize to
    unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
    io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);

    // A fixed list, so the check is about layout and not about this machine.
    app->font_scanned = true;
    app->font_files.clear();
    app->font_files.push_back("/usr/share/fonts/TTF/DejaVuSansMono-BoldOblique.ttf");
    app->font_files.push_back("/usr/share/fonts/Adwaita/AdwaitaMono-Regular.ttf");
    app->font_files.push_back("/home/adam/.local/share/fonts/a-very-long-user-font-directory-name/"
                              "a-very-long-user-font-file-name.ttf");
    snprintf(app->font, sizeof(app->font), "%s", app->font_files[0].c_str());
    snprintf(app->font_msg, sizeof(app->font_msg),
             "Loaded %s at 20 px", app->font_files[2].c_str());
    app->options_open = true;

    for (int f = 0; f < 3; f++) {
        ImGui::NewFrame();
        app_panes_render(app);
        ImGui::Render();
    }
    ImGuiWindow* w = ImGui::FindWindowByName("Options");
    CHECK(w != nullptr);
    if (w) {
        CHECK(w->Pos.x >= 0 && w->Pos.y >= 0);
        CHECK(w->Size.x <= io.DisplaySize.x + 1.0f);
        CHECK(w->Size.y <= io.DisplaySize.y + 1.0f);
        CHECK(w->DC.CursorMaxPos.x <= w->Pos.x + w->Size.x + 0.5f);
        if (w->DC.CursorMaxPos.x > w->Pos.x + w->Size.x + 0.5f)
            printf("options overflow: max %.0f vs right %.0f\n",
                   w->DC.CursorMaxPos.x, w->Pos.x + w->Size.x);
    }

    // The four menu titles fit the same narrow window: a menu bar that runs out
    // of room truncates rather than wraps.
    float mw = 0;
    const ImGuiStyle& st = ImGui::GetStyle();
    const char* titles[] = { "File", "Commands", "Options", "Help" };
    for (int i = 0; i < 4; i++) {
        mw += ImGui::CalcTextSize(titles[i]).x + st.FramePadding.x * 2.0f;
        if (i) mw += st.ItemSpacing.x;
    }
    CHECK(mw <= io.DisplaySize.x);

    // The hinting block is drawn and not merely compiled: its one-line
    // explanation differs per mode, so the mode with the longer note makes the
    // dialog taller - and the wider note still has to stay inside the frame.
    if (mc_font_hinting_available()) {
        auto bottom_with = [&](const char* mode) -> float {
            snprintf(app->hinting, sizeof(app->hinting), "%s", mode);
            for (int f = 0; f < 2; f++) {
                ImGui::NewFrame();
                app_panes_render(app);
                ImGui::Render();
            }
            ImGuiWindow* d = ImGui::FindWindowByName("Options");
            if (d) CHECK(d->DC.CursorMaxPos.x <= d->Pos.x + d->Size.x + 0.5f);
            return d ? d->DC.CursorMaxPos.y : 0.0f;
        };
        CHECK(bottom_with("default") > 0.0f);
        CHECK(bottom_with("none") > bottom_with("default"));
        snprintf(app->hinting, sizeof(app->hinting), "default");
    }

    app->options_open = false;
    app->options_field_active = false;
    app->font_scanned = false;
    app->font_files.clear();
    app->font_msg[0] = '\0';
    app->font_filter[0] = '\0';
    ImGui::DestroyContext(ctx);
}

// The menu bar only exists if the window it belongs to asks for it: BeginMenuBar()
// returns false without ImGuiWindowFlags_MenuBar, which leaves four menus in the
// source and a blank strip on screen. Measuring the titles is not enough - that
// passes either way - so this asks ImGui what the window actually drew.
static void test_menu_bar(AppPanes* app) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(900, 600);
    unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
    io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);

    for (int f = 0; f < 2; f++) {
        ImGui::NewFrame();
        app_panes_render(app);
        ImGui::Render();
    }
    ImGuiWindow* root = ImGui::FindWindowByName("Midnight Commander");
    CHECK(root != nullptr);
    if (root) {
        CHECK(root->MenuBarHeight > 0.0f);                                  // the flag is set
        CHECK(root->DC.NavLayersActiveMask & (1 << ImGuiNavLayer_Menu));    // and the bar ran
        // The panes start below the bar rather than underneath it.
        // The bar sits at the top of the window and the panes are drawn under
        // it, so the strip is not sitting on top of the file list.
        ImRect bar = root->MenuBarRect();
        CHECK(bar.Min.x == root->Pos.x && bar.Min.y == root->Pos.y);
        CHECK(bar.Max.y > bar.Min.y && root->DC.CursorMaxPos.y > bar.Max.y);
    }
    ImGui::DestroyContext(ctx);
}

// A menu bar that is drawn but does not answer to the mouse is the same as no
// menu bar. The trap is the command line at the bottom of the same window: it
// asks for the keyboard on every frame, a request lands on the *next* frame, and
// it takes ActiveId away from the item in the middle of being clicked, so the
// press never survives the release and the item silently does nothing.
static void test_menu_click(AppPanes* app) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(900, 600);
    unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
    io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);

    auto frame = [app]() {
        ImGui::NewFrame();
        app_panes_render(app);
        ImGui::Render();
    };

    frame(); frame();
    ImGuiWindow* root = ImGui::FindWindowByName("Midnight Commander");
    CHECK(root != nullptr);
    if (!root) { ImGui::DestroyContext(ctx); return; }

    ImRect bar = root->MenuBarRect();
    bool view_before = app->left.quick_view;

    // Press and release on the first title.
    io.AddMousePosEvent(bar.Min.x + 8.0f, bar.Min.y + bar.GetHeight() * 0.5f);
    frame();
    io.AddMouseButtonEvent(0, true);
    frame();
    io.AddMouseButtonEvent(0, false);
    frame(); frame();
    CHECK(ImGui::IsPopupOpen((ImGuiID)0, ImGuiPopupFlags_AnyPopup));   // it dropped down

    // The dropdown is its own window; click its first row, "View".
    ImGuiWindow* menu = nullptr;
    for (ImGuiWindow* w : ctx->Windows)
        if ((w->Flags & ImGuiWindowFlags_Popup) && w->Active) menu = w;
    CHECK(menu != nullptr);
    if (menu) {
        float pad = ImGui::GetStyle().WindowPadding.y;
        io.AddMousePosEvent(menu->Pos.x + 20.0f, menu->Pos.y + pad + ImGui::GetFrameHeight() * 0.5f);
        frame();
        io.AddMouseButtonEvent(0, true);
        frame();
        io.AddMouseButtonEvent(0, false);
        frame();
        CHECK(app->left.quick_view != view_before);   // the item fired
        app->left.quick_view = view_before;           // leave the app as found
    }

    // With the menu gone the command line takes the keyboard back, so the two
    // rules hold at once: typing works, clicking works.
    frame(); frame();
    CHECK(!ImGui::IsPopupOpen((ImGuiID)0, ImGuiPopupFlags_AnyPopup));
    CHECK(ImGui::GetActiveID() != 0);
    ImGui::DestroyContext(ctx);
}

// Ctrl+S opens the quick filter and puts the caret in it, so the keys typed
// straight after belong to the filter and not to the pane behind it.
static void test_filter_focus(AppPanes* app, const std::string& root) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(900, 600);
    unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
    io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);

    // ImGui resolves a focus request at the start of the next frame, so a frame
    // is not enough to see the result - one more is.
    auto frame = [app](int n) {
        for (int i = 0; i < n; i++) {
            ImGui::NewFrame();
            app_panes_render(app);
            ImGui::Render();
        }
    };

    Pane& pane = app->left;
    refresh_pane(&pane, root.c_str());
    app->left_focus = true;
    pane.filter[0] = '\0';
    pane.filter_active = false;
    pane.filter_focus_request = false;
    pane.filter_field_active = false;

    app_panes_handle_key(app, SDLK_S, SDL_KMOD_CTRL);
    CHECK(pane.filter_active);
    CHECK(pane.filter_focus_request);

    frame(2);
    // The field itself, not the row above it: SetKeyboardFocusHere(-1) asked for
    // the previous item and the caret landed nowhere the user could see.
    CHECK(pane.filter_field_active);

    // And typing works from that frame on, fed the way the SDL backend feeds it.
    io.AddInputCharacter('g');
    io.AddInputCharacter('a');
    frame(1);
    CHECK(!strcmp(pane.filter, "ga"));
    CHECK(pane.filter_field_active);

    // The filter is live: the view shrinks to what matches, and the row the
    // cursor sits on is one of them.
    rebuild_view(pane);
    CHECK(pane.view.size() > 0);
    for (int i = 0; i < (int)pane.view.size(); i++) {
        const char* name = pane.entries[pane.view[i]]->name;
        if (!strcmp(name, "..")) continue;   // the parent row always stays
        CHECK(filter_matches(name, pane.filter));
    }
    CHECK(strcmp(pane.filter_applied, "ga") == 0);

    // Ctrl+S in the other pane focuses that pane's field, not the first one.
    app->left.filter_field_active = false;
    app->left_focus = false;
    refresh_pane(&app->right, root.c_str());
    app->right.filter[0] = '\0';
    app->right.filter_active = false;
    app->right.filter_field_active = false;
    app_panes_handle_key(app, SDLK_S, SDL_KMOD_CTRL);
    CHECK(app->right.filter_focus_request);
    frame(2);
    CHECK(app->right.filter_field_active);
    CHECK(!app->left.filter_field_active);

    app->left.filter[0] = '\0';
    app->left.filter_active = false;
    app->right.filter[0] = '\0';
    app->right.filter_active = false;
    app->right.filter_field_active = false;
    app->left_focus = true;
    rebuild_view(app->left);
    ImGui::DestroyContext(ctx);
}

// A focus request is answered at the start of the next frame, against whichever
// window holds focus by then - so a window that appears in between, the F3
// preview or any dialog, takes the answer and the field stays unfocused. The
// request is repeated until the field has the keyboard; this is what proves it.
static void test_filter_focus_preview(AppPanes* app, const std::string& root) {
    ImGuiContext* ctx = ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.IniFilename = nullptr;
    io.DisplaySize = ImVec2(900, 600);
    unsigned char* px = nullptr; int fw = 0, fh = 0, bpp = 0;
    io.Fonts->GetTexDataAsRGBA32(&px, &fw, &fh, &bpp);

    auto frame = [app](int n) {
        for (int i = 0; i < n; i++) {
            ImGui::NewFrame();
            app_panes_render(app);
            ImGui::Render();
        }
    };

    Pane& pane = app->left;
    refresh_pane(&pane, root.c_str());
    app->left_focus = true;
    pane.filter[0] = '\0';
    pane.filter_active = false;
    pane.filter_field_active = false;
    pane.filter_focus_request = false;
    app->left.quick_view = true;                 // the F3 preview opens this frame

    // Ctrl+S first, so the preview window appears in the very frame the request
    // is submitted and competes with it for the keyboard.
    app_panes_handle_key(app, SDLK_S, SDL_KMOD_CTRL);
    frame(4);
    CHECK(ImGui::FindWindowByName("Quick view") != nullptr);
    CHECK(pane.filter_field_active);
    io.AddInputCharacter('o');
    frame(1);
    CHECK(!strcmp(pane.filter, "o"));

    app->left.quick_view = false;
    pane.filter[0] = '\0';
    pane.filter_active = false;
    pane.filter_field_active = false;
    rebuild_view(pane);
    ImGui::DestroyContext(ctx);
}

int main() {
    char tmpl[] = "/tmp/mc-clone-test-XXXXXX";
    const char* dir = mkdtemp(tmpl);
    if (!dir) { printf("cannot create temp dir\n"); return 1; }
    std::string root(dir);

    touch_file(root, "alpha.txt");
    touch_file(root, "beta.txt");
    touch_file(root, "gamma.log");
    mkdir((root + "/sub").c_str(), 0755);
    touch_file(root + "/sub", "inner.txt");
    mkdir((root + "/sub/deep").c_str(), 0755);
    touch_file(root + "/sub/deep", "x.txt");
    touch_file(root, ".hidden");

    fs_set_sort_mode(FS_SORT_NAME);
    fs_set_show_hidden(false);

    Pane p;
    p.entries = nullptr;
    p.entry_count = 0;
    p.selected = 0;
    p.anchor = 0;
    p.scroll_request = false;
    p.current_dir[0] = '\0';

    AppPanes app;

    test_matcher();
    test_pack_dialog_layout(&app);

    refresh_pane(&p, root.c_str());
    CHECK(p.entry_count == 5);   // ..  alpha.txt  beta.txt  gamma.log  sub
    CHECK((int)p.marked.size() == p.entry_count);
    CHECK((int)p.dir_size.size() == p.entry_count);
    CHECK(p.dir_size[idx_of(p, "sub")] == -1);

    test_view_and_nav(p);
    test_mark_history(p);
    test_step_marks(p);

    refresh_pane(&p, root.c_str());
    test_clipboard_paths(p);
    test_refresh_clears_filter(p);
    test_tabs(p, root.c_str());
    test_branch_view(&app, p);
    test_fs_list_tree();
    test_fs_helpers(root);
    test_unique_copy_name(root);
    test_trash_helpers();
    test_quick_search(&app, p);
    test_columns(&app);
    test_tree_panel(&app, p, root);
    test_archive_keys();
    test_ctrl_p_and_i(&app, root);

    // An archive the panes can browse and operate on.
    sh("mkdir -p '" + root + "/src/sub'");
    touch_file(root + "/src", "one.txt");
    touch_file(root + "/src", "two.txt");
    touch_file(root + "/src/sub", "inner.txt");
    {
        StringList names;
        names.push_back("one.txt");
        names.push_back("two.txt");
        names.push_back("sub");
        std::string err;
        CHECK(arch_pack((root + "/pkg.zip").c_str(), (root + "/src").c_str(), names,
                        nullptr, nullptr, &err));
    }
    sh("rm -rf '" + root + "/src'");
    CHECK(fs_exists((root + "/pkg.zip").c_str()));

    test_archive_keys_live(&app, root);
    test_archive_browse(&app, root);
    test_archive_guards(&app, root);
    test_archive_f5_copy_out(&app, root);
    test_archive_copy_out(&app, root);
    test_archive_ops(&app, root);
    test_pack_options(&app, root);
    test_deferred_ops(&app, root);
    test_op_dialog(&app, root);
    test_ui_id_uniqueness(&app);
    test_font_scan(root);
    test_font_apply(&app, root);
    test_font_size();
    test_hinting(&app, root);
    test_display_scale();
    test_framebuffer_scale();
    test_identity(&app);
    test_title(&app);
    test_options_config(&app);
    test_config_file(root);
    test_tab_restore(&app, root);
    test_options_keys(&app);
    test_remote_keys(&app);
    test_op_tab_ring(&app);
    test_bg_transfers(&app);
    test_failed_list_has_no_rows(&app, root);
    test_quick_view(&app, root);
    test_options_dialog_layout(&app);
    test_menu_bar(&app);
    test_filter_focus(&app, root);
    test_filter_focus_preview(&app, root);
    test_menu_click(&app);
    sh("rm -rf '" + root + "/out'");

    free_entries(p.entries, p.entry_count);
    printf("%d checks, %d failures\n", checks, failures);
    return failures ? 1 : 0;
}
